const o={"ko-first-u01.title":"Animais","ko-first-u01.tip":"Olhe a figura, escute e digam juntos a palavra em coreano. Tudo bem se a criança ainda não souber ler.","ko-first-u01.w.0":"gato","ko-first-u01.w.1":"cachorrinho","ko-first-u01.w.2":"peixe","ko-first-u01.w.3":"passarinho","ko-first-u01.w.4":"vaca","ko-first-u01.w.5":"porco","ko-first-u02.title":"Coisas de comer","ko-first-u02.tip":"Olhe a figura, escute e digam juntos a palavra em coreano. Tudo bem se a criança ainda não souber ler.","ko-first-u02.w.0":"maçã","ko-first-u02.w.1":"banana","ko-first-u02.w.2":"leite","ko-first-u02.w.3":"pão","ko-first-u02.w.4":"ovo","ko-first-u02.w.5":"arroz","ko-first-u03.title":"Brinquedos","ko-first-u03.tip":"Olhe a figura, escute e digam juntos a palavra em coreano. Tudo bem se a criança ainda não souber ler.","ko-first-u03.w.0":"bola","ko-first-u03.w.1":"carro","ko-first-u03.w.2":"ursinho de pelúcia","ko-first-u03.w.3":"pipa","ko-first-u03.w.4":"trem","ko-first-u03.w.5":"barco","ko-first-u04.title":"O corpo","ko-first-u04.tip":"Olhe a figura, escute e digam juntos a palavra em coreano. Tudo bem se a criança ainda não souber ler.","ko-first-u04.w.0":"olho","ko-first-u04.w.1":"orelha","ko-first-u04.w.2":"nariz","ko-first-u04.w.3":"boca","ko-first-u04.w.4":"mão","ko-first-u04.w.5":"pé","ko-first-u05.title":"Cores","ko-first-u05.tip":"Olhe a figura, escute e digam juntos a palavra em coreano. Tudo bem se a criança ainda não souber ler.","ko-first-u05.w.0":"vermelho","ko-first-u05.w.1":"azul","ko-first-u05.w.2":"amarelo","ko-first-u05.w.3":"verde","ko-first-u05.w.4":"preto","ko-first-u05.w.5":"branco","ko-first-u06.title":"Família","ko-first-u06.tip":"Olhe a figura, escute e digam juntos a palavra em coreano. Tudo bem se a criança ainda não souber ler.","ko-first-u06.w.0":"mamãe","ko-first-u06.w.1":"papai","ko-first-u06.w.2":"bebê","ko-first-u06.w.3":"vovó","ko-first-u06.w.4":"vovô","ko-first-u06.w.5":"criança","ko-first-u07.title":"Em casa","ko-first-u07.tip":"Olhe a figura, escute e digam juntos a palavra em coreano. Tudo bem se a criança ainda não souber ler.","ko-first-u07.w.0":"casa","ko-first-u07.w.1":"cama","ko-first-u07.w.2":"cadeira","ko-first-u07.w.3":"porta","ko-first-u07.w.4":"livro","ko-first-u07.w.5":"copo","ko-first-u08.title":"Lá fora","ko-first-u08.tip":"Olhe a figura, escute e digam juntos a palavra em coreano. Tudo bem se a criança ainda não souber ler.","ko-first-u08.w.0":"sol","ko-first-u08.w.1":"lua","ko-first-u08.w.2":"estrela","ko-first-u08.w.3":"árvore","ko-first-u08.w.4":"flor","ko-first-u08.w.5":"chuva"},a={"ko-kinder-u01.title":"Vogais ㅏ ㅓ ㅗ ㅜ ㅣ","ko-kinder-u01.tip":'As letras coreanas se juntam em blocos. O ㅇ no começo não tem som, então 아 soa só "a". Diga 아, 어, 오, 우, 이 abrindo bem a boca!',"ko-kinder-u01.w.0":"bebê","ko-kinder-u01.w.1":"sorvete","ko-kinder-u01.w.2":"mamãe","ko-kinder-u01.w.3":"pato","ko-kinder-u01.w.4":"pepino","ko-kinder-u01.w.5":"leite","ko-kinder-u01.w.6":"guarda-chuva","ko-kinder-u01.w.7":"dente","ko-kinder-u01.s.0":"O bebê está dormindo.","ko-kinder-u01.s.1":"Vem vindo um pato.","ko-kinder-u01.s.2":"Leite, por favor.","ko-kinder-u02.title":"Letras ㄱ ㄴ ㄷ","ko-kinder-u02.tip":"Um bloco de letras é uma consoante mais uma vogal: ㄱ + ㅏ = 가. Toque em cada cartão para ouvir o nome da letra e depois leiam o bloco juntos.","ko-kinder-u02.w.0":"mochila","ko-kinder-u02.w.1":"carne","ko-kinder-u02.w.2":"sapatos","ko-kinder-u02.w.3":"borboleta","ko-kinder-u02.w.4":"árvore","ko-kinder-u02.w.5":"música","ko-kinder-u02.w.6":"esquilo","ko-kinder-u02.w.7":"bolota","ko-kinder-u02.s.0":"A borboleta está voando.","ko-kinder-u02.s.1":"A mochila é grande.","ko-kinder-u02.s.2":"O esquilo está comendo.","ko-kinder-u03.title":"Letras ㄹ ㅁ ㅂ","ko-kinder-u03.tip":'O ㄹ tem um som entre o "r" de "caro" e o "l". O ㅁ parece uma boca fechada, e você fecha os lábios para dizê-lo!',"ko-kinder-u03.w.0":"lámen","ko-kinder-u03.w.1":"limão","ko-kinder-u03.w.2":"cavalo","ko-kinder-u03.w.3":"chapéu","ko-kinder-u03.w.4":"arco-íris","ko-kinder-u03.w.5":"banana","ko-kinder-u03.w.6":"ônibus","ko-kinder-u03.w.7":"chuva","ko-kinder-u03.s.0":"O chapéu é bonito.","ko-kinder-u03.s.1":"O ônibus está chegando.","ko-kinder-u03.s.2":"Está chovendo.","ko-kinder-u04.title":"Letras ㅅ ㅇ ㅈ","ko-kinder-u04.tip":'O ㅇ não tem som no começo do bloco (아, 오), mas embaixo ele soa "ng" (방). O ㅅ parece uma barraquinha: 사, 소.',"ko-kinder-u04.w.0":"leão","ko-kinder-u04.w.1":"maçã","ko-kinder-u04.w.2":"vaca","ko-kinder-u04.w.3":"melancia","ko-kinder-u04.w.4":"relógio","ko-kinder-u04.w.5":"carro","ko-kinder-u04.w.6":"suco","ko-kinder-u04.w.7":"a Terra","ko-kinder-u04.s.0":"O leão é grande.","ko-kinder-u04.s.1":"Suco, por favor.","ko-kinder-u04.s.2":"A melancia está gostosa.","ko-kinder-u05.title":"Letras ㅊ ㅋ ㅌ","ko-kinder-u05.tip":'ㅊ, ㅋ, ㅌ são letras "com sopro": o ㅋ é o ㄱ com um tracinho a mais e um sopro de ar a mais. Coloque a mão na frente da boca e sinta!',"ko-kinder-u05.w.0":"saia","ko-kinder-u05.w.1":"queijo","ko-kinder-u05.w.2":"nariz","ko-kinder-u05.w.3":"elefante","ko-kinder-u05.w.4":"biscoito","ko-kinder-u05.w.5":"coelho","ko-kinder-u05.w.6":"tomate","ko-kinder-u05.w.7":"caminhão","ko-kinder-u05.s.0":"O coelho está pulando.","ko-kinder-u05.s.1":"A tromba do elefante é comprida.","ko-kinder-u05.s.2":"Um biscoito, por favor.","ko-kinder-u06.title":"Letras ㅍ ㅎ","ko-kinder-u06.tip":'O ㅎ soa como o "r" de "rato" ou o "h" do inglês: 하, 호, 후, como uma risadinha. Agora você conhece todas as 14 consoantes básicas!',"ko-kinder-u06.w.0":"uvas","ko-kinder-u06.w.1":"pizza","ko-kinder-u06.w.2":"onda","ko-kinder-u06.w.3":"pinguim","ko-kinder-u06.w.4":"hipopótamo","ko-kinder-u06.w.5":"sol","ko-kinder-u06.w.6":"tigre","ko-kinder-u06.w.7":"lenço de papel","ko-kinder-u06.s.0":"O pinguim está andando.","ko-kinder-u06.s.1":"O tigre está dormindo.","ko-kinder-u06.s.2":"As uvas estão gostosas.","ko-kinder-u07.title":"Vogais ㅑ ㅕ ㅛ ㅠ ㅐ ㅔ","ko-kinder-u07.tip":'Um tracinho a mais acrescenta um "i": ㅏ (a) → ㅑ (ia), ㅗ (o) → ㅛ (io). ㅐ e ㅔ hoje soam quase igual — até os coreanos confundem!',"ko-kinder-u07.w.0":"beisebol","ko-kinder-u07.w.1":"raposa","ko-kinder-u07.w.2":"cozinhar","ko-kinder-u07.w.3":"fantasma","ko-kinder-u07.w.4":"lagarta","ko-kinder-u07.w.5":"cachorro","ko-kinder-u07.w.6":"pera","ko-kinder-u07.w.7":"caranguejo","ko-kinder-u07.s.0":"A raposa está sorrindo.","ko-kinder-u07.s.1":"O caranguejo está andando.","ko-kinder-u07.s.2":"Estou cozinhando.","ko-kinder-u08.title":"Letras de baixo (batchim)","ko-kinder-u08.tip":"Uma consoante pode ficar embaixo do bloco: ㄱ + ㅗ + ㅁ = 곰. Essa letra de baixo se chama batchim (받침). Agora você já consegue ler quase qualquer palavra coreana!","ko-kinder-u08.w.0":"urso","ko-kinder-u08.w.1":"bola","ko-kinder-u08.w.2":"neve","ko-kinder-u08.w.3":"montanha","ko-kinder-u08.w.4":"pão","ko-kinder-u08.w.5":"estrela","ko-kinder-u08.w.6":"lua","ko-kinder-u08.w.7":"água","ko-kinder-u08.s.0":"O urso está dormindo.","ko-kinder-u08.s.1":"Está nevando.","ko-kinder-u08.s.2":"Água, por favor."},e={"ko-g12-u01.title":"Cumprimentos","ko-g12-u01.tip":"Incline-se um pouquinho quando disser 안녕하세요 — é assim que os coreanos cumprimentam. Com amigos próximos, você pode dizer só 안녕!","ko-g12-u01.w.0":"olá","ko-g12-u01.w.1":"tchau (para quem vai embora)","ko-g12-u01.w.2":"obrigado","ko-g12-u01.w.3":"desculpa","ko-g12-u01.w.4":"sim","ko-g12-u01.w.5":"não","ko-g12-u01.w.6":"amigo","ko-g12-u01.w.7":"professor","ko-g12-u01.w.8":"boa noite","ko-g12-u01.s.0":"Olá, professora.","ko-g12-u01.s.1":"Sim, obrigado.","ko-g12-u01.s.2":"Não, tudo bem.","ko-g12-u01.s.3":"Me desculpe mesmo.","ko-g12-u01.s.4":"Oi, amigo!","ko-g12-u01.s.5":"Boa noite, mamãe.","ko-g12-u02.title":"Números de 1 a 10","ko-g12-u02.tip":"O coreano tem dois conjuntos de números. 하나, 둘, 셋 são usados para contar coisas e dizer a idade. Conte os dedos com eles!","ko-g12-u02.w.0":"um","ko-g12-u02.w.1":"dois","ko-g12-u02.w.2":"três","ko-g12-u02.w.3":"quatro","ko-g12-u02.w.4":"cinco","ko-g12-u02.w.5":"seis","ko-g12-u02.w.6":"sete","ko-g12-u02.w.7":"oito","ko-g12-u02.w.8":"nove","ko-g12-u02.w.9":"dez","ko-g12-u02.s.0":"Um, dois, três!","ko-g12-u02.s.1":"Quatro, cinco, seis.","ko-g12-u02.s.2":"Sete, oito, nove, dez.","ko-g12-u02.s.3":"Eu tenho cinco anos.","ko-g12-u02.s.4":"Eu tenho dez dedos.","ko-g12-u02.s.5":"Mais um, por favor.","ko-g12-u03.title":"Cores","ko-g12-u03.tip":"Todas as palavras de cor terminam em 색 (cor). Aponte para as coisas ao seu redor e diga a cor: 빨간색!","ko-g12-u03.w.0":"vermelho","ko-g12-u03.w.1":"azul","ko-g12-u03.w.2":"amarelo","ko-g12-u03.w.3":"verde","ko-g12-u03.w.4":"roxo","ko-g12-u03.w.5":"laranja (cor)","ko-g12-u03.w.6":"rosa","ko-g12-u03.w.7":"preto","ko-g12-u03.w.8":"branco","ko-g12-u03.s.0":"As maçãs são vermelhas.","ko-g12-u03.s.1":"O céu é azul.","ko-g12-u03.s.2":"As bananas são amarelas.","ko-g12-u03.s.3":"As folhas são verdes.","ko-g12-u03.s.4":"As uvas são roxas.","ko-g12-u03.s.5":"Eu gosto de rosa.","ko-g12-u04.title":"Família","ko-g12-u04.tip":'Os coreanos dizem 우리 (nosso) em vez de "meu" para a família e a casa: 우리 엄마, 우리 집. Soa carinhoso e acolhedor.',"ko-g12-u04.w.0":"família","ko-g12-u04.w.1":"mamãe","ko-g12-u04.w.2":"papai","ko-g12-u04.w.3":"vovó","ko-g12-u04.w.4":"vovô","ko-g12-u04.w.5":"irmãozinho ou irmãzinha","ko-g12-u04.w.6":"bebê","ko-g12-u04.w.7":"cachorrinho","ko-g12-u04.s.0":"Esta é a minha família.","ko-g12-u04.s.1":"Mamãe, eu te amo.","ko-g12-u04.s.2":"O papai é alto.","ko-g12-u04.s.3":"A vovó está sorrindo.","ko-g12-u04.s.4":"Meu irmãozinho está chorando.","ko-g12-u04.s.5":"O cachorrinho também é da família.","ko-g12-u05.title":"Animais","ko-g12-u05.tip":"Os sons dos animais em coreano são divertidos: o gato faz 야옹, o cachorro faz 멍멍 e o sapo faz 개굴개굴. Experimente!","ko-g12-u05.w.0":"gato","ko-g12-u05.w.1":"macaco","ko-g12-u05.w.2":"girafa","ko-g12-u05.w.3":"rato","ko-g12-u05.w.4":"cobra","ko-g12-u05.w.5":"galinha","ko-g12-u05.w.6":"ovelha","ko-g12-u05.w.7":"tartaruga","ko-g12-u05.w.8":"sapo","ko-g12-u05.s.0":"O gato faz miau.","ko-g12-u05.s.1":"As girafas têm o pescoço comprido.","ko-g12-u05.s.2":"O macaco está comendo uma banana.","ko-g12-u05.s.3":"As tartarugas são lentas.","ko-g12-u05.s.4":"O sapo pula.","ko-g12-u05.s.5":"A ovelha está comendo grama.","ko-g12-u06.title":"Frutas","ko-g12-u06.tip":"배 quer dizer pera — e também barco e barriga! A figura mostra qual é.","ko-g12-u06.w.0":"maçã","ko-g12-u06.w.1":"banana","ko-g12-u06.w.2":"morango","ko-g12-u06.w.3":"uvas","ko-g12-u06.w.4":"melancia","ko-g12-u06.w.5":"tangerina","ko-g12-u06.w.6":"pêssego","ko-g12-u06.w.7":"pera","ko-g12-u06.w.8":"kiwi","ko-g12-u06.s.0":"O morango é vermelho.","ko-g12-u06.s.1":"A tangerina é doce.","ko-g12-u06.s.2":"Eu gosto de pêssego.","ko-g12-u06.s.3":"A melancia é muito grande.","ko-g12-u06.s.4":"Uvas, por favor.","ko-g12-u06.s.5":"Os kiwis são verdes.","ko-g12-u07.title":"Comida","ko-g12-u07.tip":"Antes de comer, os coreanos dizem 잘 먹겠습니다 (vou comer bem) e, depois de comer, 잘 먹었습니다. Experimente na próxima refeição!","ko-g12-u07.w.0":"arroz","ko-g12-u07.w.1":"kimchi","ko-g12-u07.w.2":"sopa","ko-g12-u07.w.3":"gimbap (rolinho de arroz)","ko-g12-u07.w.4":"bolinho de arroz","ko-g12-u07.w.5":"guioza","ko-g12-u07.w.6":"ovo","ko-g12-u07.w.7":"peixe (para comer)","ko-g12-u07.w.8":"colher","ko-g12-u07.w.9":"hashi (pauzinhos)","ko-g12-u07.s.0":"Eu como arroz.","ko-g12-u07.s.1":"O kimchi é apimentado.","ko-g12-u07.s.2":"Os guiozas estão gostosos.","ko-g12-u07.s.3":"A sopa está quente.","ko-g12-u07.s.4":"Eu como com hashi.","ko-g12-u07.s.5":"Gimbap, por favor.","ko-g12-u07.s.6":"Estou com fome.","ko-g12-u08.title":"O corpo","ko-g12-u08.tip":'Brinque de "O mestre mandou" em coreano: 코! 귀! 머리! Toque cada parte do corpo quando ouvir.',"ko-g12-u08.w.0":"cabeça","ko-g12-u08.w.1":"olho","ko-g12-u08.w.2":"nariz","ko-g12-u08.w.3":"boca","ko-g12-u08.w.4":"orelha","ko-g12-u08.w.5":"mão","ko-g12-u08.w.6":"pé","ko-g12-u08.w.7":"perna","ko-g12-u08.w.8":"braço","ko-g12-u08.s.0":"Eu tenho dois olhos.","ko-g12-u08.s.1":"Toque o nariz.","ko-g12-u08.s.2":"Eu lavo as mãos.","ko-g12-u08.s.3":"Abra bem a boca.","ko-g12-u08.s.4":"Minha cabeça está doendo.","ko-g12-u08.s.5":"Minhas pernas são compridas.","ko-g12-u09.title":"A escola","ko-g12-u09.tip":"Na Coreia, os alunos chamam o professor de 선생님 — nunca só pelo nome. 님 é uma terminação educada que mostra respeito.","ko-g12-u09.w.0":"escola","ko-g12-u09.w.1":"sala de aula","ko-g12-u09.w.2":"lápis","ko-g12-u09.w.3":"borracha","ko-g12-u09.w.4":"caderno","ko-g12-u09.w.5":"tesoura","ko-g12-u09.w.6":"carteira (mesa)","ko-g12-u09.w.7":"lousa","ko-g12-u09.w.8":"lição de casa","ko-g12-u09.s.0":"Eu vou para a escola.","ko-g12-u09.s.1":"Eu tenho um lápis.","ko-g12-u09.s.2":"Me empresta uma borracha, por favor.","ko-g12-u09.s.3":"Eu escrevo no meu caderno.","ko-g12-u09.s.4":"Eu tenho muita lição de casa.","ko-g12-u09.s.5":"Professora, eu tenho uma pergunta!","ko-g12-u10.title":"Em casa","ko-g12-u10.tip":"Os coreanos tiram os sapatos na porta antes de entrar. O chão costuma ser quentinho (aquecimento ondol) — que aconchegante!","ko-g12-u10.w.0":"casa","ko-g12-u10.w.1":"quarto","ko-g12-u10.w.2":"cozinha","ko-g12-u10.w.3":"banheiro","ko-g12-u10.w.4":"luz (lâmpada)","ko-g12-u10.w.5":"porta","ko-g12-u10.w.6":"sofá","ko-g12-u10.w.7":"geladeira","ko-g12-u10.w.8":"TV","ko-g12-u10.s.0":"A nossa casa é pequena.","ko-g12-u10.s.1":"Este é o meu quarto.","ko-g12-u10.s.2":"A mamãe está na cozinha.","ko-g12-u10.s.3":"Eu acendo a luz.","ko-g12-u10.s.4":"Eu me sento no sofá.","ko-g12-u10.s.5":"Onde fica o banheiro?","ko-g12-u11.title":"Roupas","ko-g12-u11.tip":'O coreano usa verbos diferentes para "vestir": 입어요 para roupas, 신어요 para meias e sapatos, 써요 para chapéus. Engraçado, né?',"ko-g12-u11.w.0":"roupa","ko-g12-u11.w.1":"camiseta","ko-g12-u11.w.2":"calça","ko-g12-u11.w.3":"saia","ko-g12-u11.w.4":"meias","ko-g12-u11.w.5":"sapatos","ko-g12-u11.w.6":"chapéu","ko-g12-u11.w.7":"luvas","ko-g12-u11.w.8":"pijama","ko-g12-u11.s.0":"Eu visto a roupa.","ko-g12-u11.s.1":"Eu calço as meias.","ko-g12-u11.s.2":"Eu ponho o chapéu.","ko-g12-u11.s.3":"Meus sapatos estão pequenos.","ko-g12-u11.s.4":"As luvas são quentinhas.","ko-g12-u11.s.5":"O pijama é bonito.","ko-g12-u12.title":"O tempo","ko-g12-u12.tip":'Em coreano, a chuva e a neve "vêm": 비가 와요, 눈이 와요. A Coreia tem quatro estações bem marcadas — de qual você gosta?',"ko-g12-u12.w.0":"tempo (clima)","ko-g12-u12.w.1":"sol","ko-g12-u12.w.2":"chuva","ko-g12-u12.w.3":"neve","ko-g12-u12.w.4":"vento","ko-g12-u12.w.5":"nuvem","ko-g12-u12.w.6":"primavera","ko-g12-u12.w.7":"verão","ko-g12-u12.w.8":"outono","ko-g12-u12.w.9":"inverno","ko-g12-u12.s.0":"O tempo está bom.","ko-g12-u12.s.1":"Está chovendo.","ko-g12-u12.s.2":"Está nevando.","ko-g12-u12.s.3":"Está ventando.","ko-g12-u12.s.4":"O verão é quente.","ko-g12-u12.s.5":"O inverno é frio.","ko-g12-u12.s.6":"Na primavera as flores desabrocham.","ko-g12-u13.title":"Dias e horas","ko-g12-u13.tip":"Todos os dias terminam em 요일 (dia da semana). 토요일 e 일요일 são o fim de semana — oba!","ko-g12-u13.w.0":"segunda-feira","ko-g12-u13.w.1":"sexta-feira","ko-g12-u13.w.2":"sábado","ko-g12-u13.w.3":"domingo","ko-g12-u13.w.4":"hoje","ko-g12-u13.w.5":"amanhã","ko-g12-u13.w.6":"ontem","ko-g12-u13.w.7":"manhã","ko-g12-u13.w.8":"noite","ko-g12-u13.s.0":"Hoje é segunda-feira.","ko-g12-u13.s.1":"Amanhã é sábado.","ko-g12-u13.s.2":"Eu descanso no domingo.","ko-g12-u13.s.3":"Eu acordo de manhã.","ko-g12-u13.s.4":"Eu durmo à noite.","ko-g12-u13.s.5":"Eu gosto de sexta-feira.","ko-g12-u14.title":"Meios de transporte","ko-g12-u14.tip":'Em coreano, você "anda" em qualquer veículo com o mesmo verbo: 버스를 타요, 자전거를 타요, 비행기를 타요.',"ko-g12-u14.w.0":"ônibus","ko-g12-u14.w.1":"metrô","ko-g12-u14.w.2":"táxi","ko-g12-u14.w.3":"trem","ko-g12-u14.w.4":"avião","ko-g12-u14.w.5":"bicicleta","ko-g12-u14.w.6":"navio","ko-g12-u14.w.7":"carro","ko-g12-u14.w.8":"estrada","ko-g12-u14.s.0":"Eu pego o ônibus.","ko-g12-u14.s.1":"O metrô é rápido.","ko-g12-u14.s.2":"Eu ando de bicicleta.","ko-g12-u14.s.3":"O avião voa.","ko-g12-u14.s.4":"O trem é comprido.","ko-g12-u14.s.5":"A estrada está congestionada.","ko-g12-u15.title":"Brinquedos e brincadeiras","ko-g12-u15.tip":'No esconde-esconde, as crianças coreanas contam e gritam 꼭꼭 숨어라, 머리카락 보일라 — "Se esconde direito, estou vendo seu cabelo!"',"ko-g12-u15.w.0":"brinquedo","ko-g12-u15.w.1":"boneca","ko-g12-u15.w.2":"blocos de montar","ko-g12-u15.w.3":"bola","ko-g12-u15.w.4":"patinete","ko-g12-u15.w.5":"quebra-cabeça","ko-g12-u15.w.6":"balão","ko-g12-u15.w.7":"jogo","ko-g12-u15.w.8":"esconde-esconde","ko-g12-u15.s.0":"Vamos brincar juntos!","ko-g12-u15.s.1":"Eu jogo a bola.","ko-g12-u15.s.2":"Eu ando de patinete.","ko-g12-u15.s.3":"Eu construo uma casa com blocos.","ko-g12-u15.s.4":"O balão está voando para longe.","ko-g12-u15.s.5":"Vamos brincar de esconde-esconde.","ko-g12-u16.title":"Natureza","ko-g12-u16.tip":"Grande parte da Coreia é coberta de montanhas, por isso fazer trilha (등산) é um passeio de família favorito no fim de semana.","ko-g12-u16.w.0":"montanha","ko-g12-u16.w.1":"mar","ko-g12-u16.w.2":"rio","ko-g12-u16.w.3":"céu","ko-g12-u16.w.4":"flor","ko-g12-u16.w.5":"árvore","ko-g12-u16.w.6":"grama","ko-g12-u16.w.7":"areia","ko-g12-u16.w.8":"estrela","ko-g12-u16.s.0":"A montanha é alta.","ko-g12-u16.s.1":"O mar é imenso.","ko-g12-u16.s.2":"O céu está limpo.","ko-g12-u16.s.3":"A flor é bonita.","ko-g12-u16.s.4":"A árvore é grande.","ko-g12-u16.s.5":"Há muitas estrelas no céu à noite.","ko-g12-u17.title":"Sentimentos","ko-g12-u17.tip":'Em coreano, as palavras de sentimento funcionam como verbos: 기뻐요 já quer dizer "estou feliz". Se alguém parecer triste, pergunte 괜찮아요?',"ko-g12-u17.w.0":"feliz","ko-g12-u17.w.1":"triste","ko-g12-u17.w.2":"bravo","ko-g12-u17.w.3":"com medo","ko-g12-u17.w.4":"cansado","ko-g12-u17.w.5":"animado","ko-g12-u17.w.6":"entediado","ko-g12-u17.w.7":"tudo bem","ko-g12-u17.s.0":"Eu estou feliz.","ko-g12-u17.s.1":"Meu amigo está triste.","ko-g12-u17.s.2":"Estou muito cansado.","ko-g12-u17.s.3":"Hoje é um dia muito emocionante!","ko-g12-u17.s.4":"Você está bem mesmo?","ko-g12-u17.s.5":"Sim, estou bem.","ko-g12-u18.title":"Ações","ko-g12-u18.tip":'Palavras que terminam em 요 são educadas. 가요 pode querer dizer "eu vou", "você vai" ou "vamos" — a situação mostra qual!',"ko-g12-u18.w.0":"ir","ko-g12-u18.w.1":"vir","ko-g12-u18.w.2":"comer","ko-g12-u18.w.3":"beber","ko-g12-u18.w.4":"dormir","ko-g12-u18.w.5":"correr","ko-g12-u18.w.6":"ler","ko-g12-u18.w.7":"olhar","ko-g12-u18.w.8":"sentar","ko-g12-u18.s.0":"Eu bebo água.","ko-g12-u18.s.1":"Eu leio um livro.","ko-g12-u18.s.2":"Corra rápido!","ko-g12-u18.s.3":"Sente aqui.","ko-g12-u18.s.4":"Olhe para o céu.","ko-g12-u18.s.5":"Eu vou para casa.","ko-g12-u19.title":"Nosso bairro","ko-g12-u19.tip":"Muitas palavras de lugares terminam em 원, 관 ou 국 — 병원, 도서관, 우체국. Elas vêm de antigos caracteres chineses para prédios.","ko-g12-u19.w.0":"bairro","ko-g12-u19.w.1":"loja","ko-g12-u19.w.2":"hospital","ko-g12-u19.w.3":"parque","ko-g12-u19.w.4":"biblioteca","ko-g12-u19.w.5":"padaria","ko-g12-u19.w.6":"correio","ko-g12-u19.w.7":"parquinho","ko-g12-u19.w.8":"delegacia","ko-g12-u19.s.0":"Eu vou ao parque.","ko-g12-u19.s.1":"A padaria é perto.","ko-g12-u19.s.2":"Eu leio livros na biblioteca.","ko-g12-u19.s.3":"Eu brinco no parquinho.","ko-g12-u19.s.4":"Onde fica o hospital?","ko-g12-u19.s.5":"A loja é grande.","ko-g12-u20.title":"Festa de aniversário","ko-g12-u20.tip":'No aniversário, os coreanos tomam 미역국 (sopa de algas) — as mães tomam essa sopa depois de dar à luz, então ela quer dizer "obrigado, mamãe".',"ko-g12-u20.w.0":"aniversário","ko-g12-u20.w.1":"festa","ko-g12-u20.w.2":"presente","ko-g12-u20.w.3":"bolo","ko-g12-u20.w.4":"vela","ko-g12-u20.w.5":"música","ko-g12-u20.w.6":"cartão","ko-g12-u20.w.7":"sopa de algas","ko-g12-u20.w.8":"parabéns","ko-g12-u20.s.0":"Feliz aniversário!","ko-g12-u20.s.1":"Obrigado pelo presente.","ko-g12-u20.s.2":"O bolo está gostoso.","ko-g12-u20.s.3":"Eu apago as velas.","ko-g12-u20.s.4":"Nós cantamos uma música.","ko-g12-u20.s.5":"Eu tomo sopa de algas."},u={"ko-g34-u01.title":"Eu sou…: se apresentando","ko-g34-u01.tip":"Olhe o último bloco da palavra: 학생 termina em ㅇ, então fica 학생이에요. 의사 não tem letra embaixo, então fica 의사예요.","ko-g34-u01.w.0":"estudante","ko-g34-u01.w.1":"médico","ko-g34-u01.w.2":"cozinheiro","ko-g34-u01.w.3":"cantor","ko-g34-u01.w.4":"policial","ko-g34-u01.w.5":"nome","ko-g34-u01.w.6":"país","ko-g34-u01.w.7":"pessoa","ko-g34-u01.w.8":"Coreia","ko-g34-u01.w.9":"eu (formal)","ko-g34-u01.s.0":"Eu sou aluno do fundamental.","ko-g34-u01.s.1":"Meu nome é Minjun.","ko-g34-u01.s.2":"Eu sou americano.","ko-g34-u01.s.3":"Meu pai é médico.","ko-g34-u01.s.4":"Esta pessoa é minha amiga.","ko-g34-u01.s.5":"Eu tenho dez anos.","ko-g34-u01.s.6":"A professora é coreana.","ko-g34-u01.s.7":"Prazer em te conhecer.","ko-g34-u01.g.title":"Dizer quem você é: 이에요 / 예요","ko-g34-u01.g.x.0":'Para dizer "A é B", coloque 이에요 ou 예요 logo depois de B: 저는 학생이에요 (eu sou estudante).',"ko-g34-u01.g.x.1":"Se B termina com uma letra embaixo (batchim), use 이에요: 학생이에요. Se não, use 예요: 의사예요.","ko-g34-u01.g.x.2":'저 quer dizer "eu" quando você fala com educação, e 제 quer dizer "meu": 제 이름은 지우예요.',"ko-g34-u01.g.0":"Eu sou estudante.","ko-g34-u01.g.1":"Eu sou médico.","ko-g34-u01.g.2":"Meu nome é Seoyeon.","ko-g34-u01.g.3":"Eu sou cantor.","ko-g34-u01.g.4":"Eu sou coreano.","ko-g34-u01.g.5":"Eu sou cozinheiro.","ko-g34-u01.g.5.task":"Troque 학생 por 요리사 (cozinheiro).","ko-g34-u01.g.6":"Minha mãe é policial.","ko-g34-u01.g.6.task":"Troque 의사 por 경찰 (policial).","ko-g34-u01.g.7":"Minha amiga é canadense.","ko-g34-u01.g.7.task":"Comece com 제 친구는 (meu amigo).","ko-g34-u01.st.title":"Uma nova amiga","ko-g34-u01.st.l.0":"Olá! Eu sou o Minjun.","ko-g34-u01.st.l.1":"Oi! Eu sou a Emma.","ko-g34-u01.st.l.2":"Emma, de que país você é?","ko-g34-u01.st.l.3":"Eu sou inglesa.","ko-g34-u01.st.l.4":"Prazer em te conhecer!","ko-g34-u01.st.l.5":"O prazer é meu.","ko-g34-u01.st.q.0":"De onde a Emma é?","ko-g34-u01.st.q.0.o.0":"영국","ko-g34-u01.st.q.0.o.1":"한국","ko-g34-u01.st.q.0.o.2":"미국","ko-g34-u01.st.q.1":"Qual é o nome do menino?","ko-g34-u01.st.q.1.o.0":"민준","ko-g34-u01.st.q.1.o.1":"엠마","ko-g34-u01.st.q.1.o.2":"지우","ko-g34-u02.title":"O que é isto?","ko-g34-u02.tip":"Aponte enquanto fala! 이거 está na sua mão, 그거 está na mão do seu amigo e 저거 está longe de vocês dois.","ko-g34-u02.w.0":"carteira","ko-g34-u02.w.1":"óculos","ko-g34-u02.w.2":"chave","ko-g34-u02.w.3":"celular","ko-g34-u02.w.4":"foto","ko-g34-u02.w.5":"coisa","ko-g34-u02.w.6":"isto","ko-g34-u02.w.7":"isso (perto de você)","ko-g34-u02.w.8":"aquilo (lá longe)","ko-g34-u02.w.9":"o quê","ko-g34-u02.s.0":"O que é isso (com você)?","ko-g34-u02.s.1":"Esta é a minha carteira.","ko-g34-u02.s.2":"Isso (com você) é um óculos?","ko-g34-u02.s.3":"Sim, é um óculos.","ko-g34-u02.s.4":"De quem é aquilo lá?","ko-g34-u02.s.5":"Aquilo é o celular da professora.","ko-g34-u02.s.6":"Estes óculos são do vovô.","ko-g34-u02.s.7":"De quem é aquela carteira lá?","ko-g34-u02.g.title":"Isto, isso, aquilo: 이 / 그 / 저","ko-g34-u02.g.x.0":"이 = isto (perto de mim), 그 = isso (perto de você), 저 = aquilo (longe de nós dois).","ko-g34-u02.g.x.1":'Acrescente 거 para dizer "coisa": 이거 (esta coisa), 그거, 저거. Ou acrescente um substantivo: 이 사진 (esta foto), 저 가방 (aquela mochila).',"ko-g34-u02.g.x.2":"Pergunte com 뭐예요: 이거 뭐예요? — O que é isto?","ko-g34-u02.g.0":"O que é isto?","ko-g34-u02.g.1":"Aquilo lá é a minha mochila.","ko-g34-u02.g.2":"Esta foto é bonita.","ko-g34-u02.g.3":"Me dá essa chave, por favor.","ko-g34-u02.g.4":"Isso (com você) é o meu celular.","ko-g34-u02.g.5":"Isto é um lápis.","ko-g34-u02.g.5.task":"Troque 그거 por 이거 (isto).","ko-g34-u02.g.6":"O que é aquilo lá?","ko-g34-u02.g.6.task":"Pergunte sobre algo que está longe: use 저거.","ko-g34-u02.g.7":"Estes óculos são bonitos.","ko-g34-u02.g.7.task":"Troque 저 por 이 (este).","ko-g34-u03.title":"Eu tenho, tem","ko-g34-u03.tip":'Uma palavra muito útil: 없어요 sozinha pode querer dizer "eu não tenho" ou "não tem". 문제 없어요! = Sem problema!',"ko-g34-u03.w.0":"dinheiro","ko-g34-u03.w.1":"tempo","ko-g34-u03.w.2":"irmãos","ko-g34-u03.w.3":"bicho de estimação","ko-g34-u03.w.4":"problema","ko-g34-u03.w.5":"compromisso (de encontro)","ko-g34-u03.w.6":"lugar (assento)","ko-g34-u03.w.7":"bala","ko-g34-u03.w.8":"um resfriado","ko-g34-u03.w.9":"ingresso","ko-g34-u03.s.0":"Eu tenho um irmãozinho.","ko-g34-u03.s.1":"Tem um pouco de dinheiro na minha carteira.","ko-g34-u03.s.2":"Você tem tempo hoje?","ko-g34-u03.s.3":"Tem um gato em casa.","ko-g34-u03.s.4":"Sem problema.","ko-g34-u03.s.5":"Amanhã eu tenho um compromisso.","ko-g34-u03.s.6":"Este lugar está ocupado?","ko-g34-u03.s.7":"Tem uma bala.","ko-g34-u03.g.title":"Ter / ter (haver): 있어요 · 없어요","ko-g34-u03.g.x.0":'있어요 quer dizer "tem" ou "eu tenho". 없어요 quer dizer "não tem" ou "eu não tenho".',"ko-g34-u03.g.x.1":"Coloque 이 ou 가 depois da coisa: 이 depois de uma letra embaixo (돈이), 가 quando não há letra embaixo (사과가).","ko-g34-u03.g.x.2":"Para perguntar, suba a voz no final: 시간 있어요? — Você tem tempo?","ko-g34-u03.g.0":"Eu não tenho dinheiro.","ko-g34-u03.g.1":"Tem uma maçã.","ko-g34-u03.g.2":"Você tem um gato?","ko-g34-u03.g.3":"Eu não tenho tempo.","ko-g34-u03.g.4":"Eu tenho um compromisso.","ko-g34-u03.g.5":"Eu não tenho irmãos.","ko-g34-u03.g.5.task":'Diga "não tenho": use 없어요.',"ko-g34-u03.g.6":"Aqui tem um ingresso.","ko-g34-u03.g.6.task":"Troque 사탕 por 표 (ingresso). Cuidado com 이/가!","ko-g34-u03.g.7":"Você tem um bicho de estimação?","ko-g34-u03.g.7.task":"Transforme em pergunta.","ko-g34-u04.title":"Quanto a mim: 은 / 는","ko-g34-u04.tip":"Na Coreia, as crianças chamam os irmãos mais velhos por estes títulos, não pelo nome. Os meninos dizem 형 e 누나; as meninas dizem 오빠 e 언니.","ko-g34-u04.w.0":"irmão mais velho (dito por um menino)","ko-g34-u04.w.1":"irmão mais velho (dito por uma menina)","ko-g34-u04.w.2":"irmã mais velha (dito por um menino)","ko-g34-u04.w.3":"irmã mais velha (dito por uma menina)","ko-g34-u04.w.4":"altura","ko-g34-u04.w.5":"cabelo","ko-g34-u04.w.6":"passatempo","ko-g34-u04.w.7":"esporte, exercício","ko-g34-u04.w.8":"música","ko-g34-u04.w.9":"jeito de ser","ko-g34-u04.s.0":"Meu irmão mais velho tem doze anos.","ko-g34-u04.s.1":"Minha irmã mais velha tem um jeito muito legal.","ko-g34-u04.s.2":"Eu sou baixinho.","ko-g34-u04.s.3":"O passatempo da minha irmã mais velha é cantar.","ko-g34-u04.s.4":"Meu irmão mais velho tem cabelo curto.","ko-g34-u04.s.5":"Eu gosto de música.","ko-g34-u04.s.6":"Meu irmão mais velho faz exercício todo dia.","ko-g34-u04.s.7":"Os gatos dormem muito.","ko-g34-u04.g.title":"Falar de um assunto: 은 / 는","ko-g34-u04.g.x.0":"은/는 marca do que você está falando (o assunto): 저는 학생이에요 — Quanto a mim, eu sou estudante.","ko-g34-u04.g.x.1":"Use 은 depois de uma letra embaixo (형은) e 는 quando não há letra embaixo (저는, 누나는).","ko-g34-u04.g.x.2":"Também mostra contraste: 형은 커요. 저는 작아요. — Meu irmão é alto, mas eu sou baixinho.","ko-g34-u04.g.0":"Eu sou o Jiwoo.","ko-g34-u04.g.1":"Meu irmão mais velho é alto.","ko-g34-u04.g.2":"Minha irmã mais velha gosta de música.","ko-g34-u04.g.3":"Os gatos são fofos.","ko-g34-u04.g.4":"Meu passatempo é desenhar.","ko-g34-u04.g.5":"Minha irmã mais velha tem cabelo comprido.","ko-g34-u04.g.5.task":"Agora fale da sua irmã mais velha (언니).","ko-g34-u04.g.6":"Meu irmãozinho é baixinho.","ko-g34-u04.g.6.task":"Troque 형 por 동생. Cuidado com 은/는!","ko-g34-u04.g.7":"Meu irmão mais velho é bom em esportes.","ko-g34-u04.g.7.task":"Fale do seu irmão mais velho (오빠).","ko-g34-u05.title":"Verbos: a terminação 요","ko-g34-u05.tip":"O 요 no final deixa a frase educada. Use com adultos e com pessoas que você acabou de conhecer — com 요 você nunca erra!","ko-g34-u05.w.0":"comprar","ko-g34-u05.w.1":"encontrar (alguém)","ko-g34-u05.w.2":"estudar","ko-g34-u05.w.3":"brincar","ko-g34-u05.w.4":"escutar","ko-g34-u05.w.5":"escrever","ko-g34-u05.w.6":"trabalhar","ko-g34-u05.w.7":"esperar","ko-g34-u05.w.8":"aprender","ko-g34-u05.w.9":"bom, legal","ko-g34-u05.s.0":"Eu aprendo coreano.","ko-g34-u05.s.1":"Eu encontro meu amigo no parque.","ko-g34-u05.s.2":"Eu compro pão.","ko-g34-u05.s.3":"Meu irmãozinho está brincando.","ko-g34-u05.s.4":"Eu escuto música.","ko-g34-u05.s.5":"A mamãe está esperando.","ko-g34-u05.s.6":"O papai está trabalhando.","ko-g34-u05.s.7":"Vamos estudar juntos.","ko-g34-u05.g.title":"Terminações educadas dos verbos: -아요 / -어요 / 해요","ko-g34-u05.g.x.0":"Os verbos coreanos mudam a terminação. Tire o 다 e acrescente uma terminação com 요: 가다 → 가요, 먹다 → 먹어요.","ko-g34-u05.g.x.1":"Se a última vogal for ㅏ ou ㅗ, acrescente 아요: 놀다 → 놀아요, 보다 → 봐요. Com outras vogais, acrescente 어요: 먹다 → 먹어요.","ko-g34-u05.g.x.2":"Os verbos que terminam em 하다 viram 해요: 공부하다 → 공부해요.","ko-g34-u05.g.x.3":"Algumas vogais se juntam: 기다리다 → 기다려요, 마시다 → 마셔요.","ko-g34-u05.g.0":"Eu encontro meu amigo.","ko-g34-u05.g.1":"Eu como arroz.","ko-g34-u05.g.2":"Eu brinco no parquinho.","ko-g34-u05.g.3":"Eu estudo coreano.","ko-g34-u05.g.4":"Eu leio um livro.","ko-g34-u05.g.5":"Eu compro pão.","ko-g34-u05.g.5.task":"Passe 사다 para a forma educada com 요.","ko-g34-u05.g.6":"Meu irmãozinho está esperando.","ko-g34-u05.g.6.task":"Passe 기다리다 para a forma educada com 요.","ko-g34-u05.g.7":"O papai trabalha numa empresa.","ko-g34-u05.g.7.task":"Passe 일하다 para a forma educada com 요.","ko-g34-u05.st.title":"O que você faz no sábado?","ko-g34-u05.st.l.0":"O que você faz no sábado?","ko-g34-u05.st.l.1":"Eu aprendo natação.","ko-g34-u05.st.l.2":"Que legal! Eu jogo futebol.","ko-g34-u05.st.l.3":"E no domingo?","ko-g34-u05.st.l.4":"Eu vou à casa da minha avó. A gente come junto.","ko-g34-u05.st.l.5":"Legal! Eu descanso em casa.","ko-g34-u05.st.q.0":"O que a Seoyeon aprende no sábado?","ko-g34-u05.st.q.0.o.0":"수영","ko-g34-u05.st.q.0.o.1":"축구","ko-g34-u05.st.q.0.o.2":"피아노","ko-g34-u05.st.q.1":"Aonde o Minjun vai no domingo?","ko-g34-u05.st.q.1.o.0":"할머니 집","ko-g34-u05.st.q.1.o.1":"학교","ko-g34-u05.st.q.1.o.2":"공원","ko-g34-u06.title":"O que você come, vê e faz: 을 / 를","ko-g34-u06.tip":"Lembre a ordem: quem → o quê → fazer. 저는 (eu) 피자를 (pizza) 먹어요 (como). A palavra de ação sempre vem por último!","ko-g34-u06.w.0":"filme","ko-g34-u06.w.1":"desenho, pintura","ko-g34-u06.w.2":"carta","ko-g34-u06.w.3":"jornal","ko-g34-u06.w.4":"piano","ko-g34-u06.w.5":"futebol","ko-g34-u06.w.6":"natação","ko-g34-u06.w.7":"faxina","ko-g34-u06.w.8":"lavar a louça","ko-g34-u06.w.9":"café","ko-g34-u06.s.0":"Eu assisto a um filme com meu irmãozinho.","ko-g34-u06.s.1":"Eu faço um desenho.","ko-g34-u06.s.2":"Eu escrevo uma carta para o meu amigo.","ko-g34-u06.s.3":"Eu toco piano.","ko-g34-u06.s.4":"Eu jogo futebol.","ko-g34-u06.s.5":"O papai lava a louça.","ko-g34-u06.s.6":"A mamãe toma café.","ko-g34-u06.s.7":"Eu arrumo o meu quarto.","ko-g34-u06.g.title":"A coisa que recebe a ação: 을 / 를","ko-g34-u06.g.x.0":"을/를 marca o objeto — a coisa que você come, vê ou faz: 사과를 먹어요 (eu como uma maçã).","ko-g34-u06.g.x.1":"Use 을 depois de uma letra embaixo (빵을) e 를 quando não há letra embaixo (커피를).","ko-g34-u06.g.x.2":"O coreano coloca o verbo bem no final: 저는 영화를 봐요 = eu · um filme · vejo.","ko-g34-u06.g.0":"Eu assisto a um filme.","ko-g34-u06.g.1":"Eu como pão.","ko-g34-u06.g.2":"Eu tomo café.","ko-g34-u06.g.3":"Eu escrevo uma carta.","ko-g34-u06.g.4":"Eu leio o jornal.","ko-g34-u06.g.5":"Eu toco piano.","ko-g34-u06.g.5.task":"Coloque o verbo no final.","ko-g34-u06.g.6":"Meu irmãozinho faz um desenho.","ko-g34-u06.g.6.task":"Coloque o verbo no final.","ko-g34-u06.g.7":"Meu irmão mais velho nada.","ko-g34-u06.g.7.task":"Troque 축구 (futebol) por 수영 (natação).","ko-g34-u07.title":"Não: 안","ko-g34-u07.tip":"Se você não gosta de comida apimentada, esta frase é útil na Coreia: 안 매운 거 있어요? — Tem alguma coisa que não seja apimentada?","ko-g34-u07.w.0":"apimentado","ko-g34-u07.w.1":"caro","ko-g34-u07.w.2":"barato","ko-g34-u07.w.3":"difícil","ko-g34-u07.w.4":"fácil","ko-g34-u07.w.5":"ocupado","ko-g34-u07.w.6":"quente (tempo)","ko-g34-u07.w.7":"doente, está doendo","ko-g34-u07.w.8":"gostoso","ko-g34-u07.w.9":"divertido","ko-g34-u07.s.0":"O tteokbokki é um pouco apimentado.","ko-g34-u07.s.1":"Este problema não é fácil.","ko-g34-u07.s.2":"Este livro não é caro.","ko-g34-u07.s.3":"O papai toma café.","ko-g34-u07.s.4":"A lição de casa não é difícil.","ko-g34-u07.s.5":"Hoje não está quente.","ko-g34-u07.s.6":"Já não está doendo.","ko-g34-u07.s.7":"O filme é muito divertido.","ko-g34-u07.g.title":"Não: 안 + verbo","ko-g34-u07.g.x.0":'Coloque 안 logo antes de um verbo ou de uma palavra que descreve para dizer "não": 매워요 → 안 매워요.',"ko-g34-u07.g.x.1":"Com verbos em 해요, o 안 vai logo antes de 해요: 공부해요 → 공부 안 해요.","ko-g34-u07.g.x.2":"맛있어요 e 재미있어요 têm seus próprios opostos: 맛없어요, 재미없어요.","ko-g34-u07.g.0":"O kimchi não é apimentado.","ko-g34-u07.g.1":"Eu não tomo café.","ko-g34-u07.g.2":"Hoje eu não estou ocupado.","ko-g34-u07.g.3":"Eu não faço a lição de casa.","ko-g34-u07.g.4":"Esta pizza não está gostosa.","ko-g34-u07.g.5":"Eu não toco piano.","ko-g34-u07.g.5.task":"Faça a negação com 안.","ko-g34-u07.g.6":"Hoje não está frio.","ko-g34-u07.g.6.task":"Faça a negação com 안.","ko-g34-u07.g.7":"Meu irmão mais velho não faz exercício.","ko-g34-u07.g.7.task":"Faça a negação. O 안 vai logo antes de 해요.","ko-g34-u08.title":"Indo a lugares: 에 가요","ko-g34-u08.tip":"Busan é a cidade grande da Coreia à beira-mar, e a ilha de Jeju (제주도) é um dos lugares favoritos para viajar em família.","ko-g34-u08.w.0":"feira","ko-g34-u08.w.1":"supermercado","ko-g34-u08.w.2":"piscina","ko-g34-u08.w.3":"cinema (teatro)","ko-g34-u08.w.4":"museu","ko-g34-u08.w.5":"zoológico","ko-g34-u08.w.6":"empresa, escritório","ko-g34-u08.w.7":"Seul","ko-g34-u08.w.8":"viagem","ko-g34-u08.w.9":"fim de semana","ko-g34-u08.s.0":"No fim de semana eu vou ao zoológico.","ko-g34-u08.s.1":"A mamãe vai à feira.","ko-g34-u08.s.2":"O papai vai ao escritório.","ko-g34-u08.s.3":"No verão eu vou à piscina.","ko-g34-u08.s.4":"Aonde você vai amanhã?","ko-g34-u08.s.5":"Eu vou ao museu.","ko-g34-u08.s.6":"Amanhã eu vou a Seul.","ko-g34-u08.s.7":"Vamos juntos ao cinema!","ko-g34-u08.g.title":"Ir a algum lugar: 에 가요 · 에 와요","ko-g34-u08.g.x.0":"Coloque 에 depois de um lugar para dizer aonde você vai: 학교에 가요 (eu vou à escola).","ko-g34-u08.g.x.1":"O 에 não muda, tenha ou não letra embaixo: 시장에, 마트에.","ko-g34-u08.g.x.2":'Pergunte com 어디: 어디에 가요? — Aonde você vai? Para "vir", use 와요: 집에 와요.',"ko-g34-u08.g.0":"Eu vou à escola.","ko-g34-u08.g.1":"Eu vou ao zoológico.","ko-g34-u08.g.2":"Aonde você vai?","ko-g34-u08.g.3":"Meu amigo vem à minha casa.","ko-g34-u08.g.4":"Nós vamos à piscina.","ko-g34-u08.g.5":"Amanhã eu vou ao museu.","ko-g34-u08.g.5.task":"Troque 극장 (cinema) por 박물관 (museu).","ko-g34-u08.g.6":"A mamãe vai à feira.","ko-g34-u08.g.6.task":"Troque 마트 por 시장 (feira).","ko-g34-u08.g.7":"Meu amigo vem à nossa casa.","ko-g34-u08.g.7.task":"Troque 가요 (ir) por 와요 (vir).","ko-g34-u08.st.title":"Planos para o fim de semana","ko-g34-u08.st.l.0":"Aonde você vai neste fim de semana?","ko-g34-u08.st.l.1":"Vou ao zoológico. Lá tem pandas!","ko-g34-u08.st.l.2":"Que legal! Com quem você vai?","ko-g34-u08.st.l.3":"Com meu pai e meu irmãozinho. E você, Jiwoo?","ko-g34-u08.st.l.4":"Vou à casa da minha avó. Ela mora em Busan.","ko-g34-u08.st.l.5":"O mar de Busan é lindo!","ko-g34-u08.st.q.0":"Aonde o Hajun vai?","ko-g34-u08.st.q.0.o.0":"동물원","ko-g34-u08.st.q.0.o.1":"바다","ko-g34-u08.st.q.0.o.2":"시장","ko-g34-u08.st.q.1":"Onde mora a avó da Jiwoo?","ko-g34-u08.st.q.1.o.0":"부산","ko-g34-u08.st.q.1.o.1":"서울","ko-g34-u08.st.q.1.o.2":"제주도","ko-g34-u09.title":"Onde está?","ko-g34-u09.tip":"Brinque de esconder um brinquedo: esconda e dê pistas em coreano — 의자 아래에 있어요! 책상 위에 있어요!","ko-g34-u09.w.0":"em cima","ko-g34-u09.w.1":"embaixo","ko-g34-u09.w.2":"do lado","ko-g34-u09.w.3":"na frente","ko-g34-u09.w.4":"atrás","ko-g34-u09.w.5":"dentro","ko-g34-u09.w.6":"fora","ko-g34-u09.w.7":"aqui","ko-g34-u09.w.8":"aí (perto de você)","ko-g34-u09.w.9":"lá (longe)","ko-g34-u09.s.0":"O gato está em cima da cama.","ko-g34-u09.s.1":"O gato está embaixo do sofá.","ko-g34-u09.s.2":"O lápis está dentro da mochila.","ko-g34-u09.s.3":"Tem um parque na frente da nossa casa.","ko-g34-u09.s.4":"A mamãe senta do meu lado.","ko-g34-u09.s.5":"O cachorrinho está atrás da porta.","ko-g34-u09.s.6":"O banheiro é lá.","ko-g34-u09.s.7":"A mamãe está lá fora.","ko-g34-u09.g.title":"Onde as coisas estão: 에 있어요 · 위 / 아래 / 옆","ko-g34-u09.g.x.0":"Use 에 있어요 para dizer onde algo está: 고양이가 방에 있어요 (o gato está no quarto).","ko-g34-u09.g.x.1":"Para um lugar exato, diga primeiro a coisa, depois a posição e depois 에: 책상 위에 (em cima da mesa), 의자 아래에 (embaixo da cadeira).","ko-g34-u09.g.x.2":"Posições: 위 em cima, 아래 embaixo, 옆 do lado, 앞 na frente, 뒤 atrás, 안 dentro, 밖 fora.","ko-g34-u09.g.0":"O livro está em cima da mesa.","ko-g34-u09.g.1":"A bola está embaixo da cadeira.","ko-g34-u09.g.2":"O gato está dentro da caixa.","ko-g34-u09.g.3":"Meu amigo está do meu lado.","ko-g34-u09.g.4":"Tem um cachorrinho atrás da árvore.","ko-g34-u09.g.5":"O leite está dentro da geladeira.","ko-g34-u09.g.5.task":"Coloque o leite dentro da geladeira: use 안.","ko-g34-u09.g.6":"O parque fica na frente da escola.","ko-g34-u09.g.6.task":"Coloque o parque na frente da escola: use 앞.","ko-g34-u09.g.7":"Os sapatos estão do lado da porta?","ko-g34-u09.g.7.task":"Transforme em pergunta.","ko-g34-u10.title":"Onde você faz: 에서","ko-g34-u10.tip":"에 é para ir ou estar em algum lugar (학교에 가요). 에서 é para fazer alguma coisa lá (학교에서 공부해요).","ko-g34-u10.w.0":"pátio da escola","ko-g34-u10.w.1":"restaurante","ko-g34-u10.w.2":"café (lugar)","ko-g34-u10.w.3":"praia","ko-g34-u10.w.4":"ginásio","ko-g34-u10.w.5":"basquete","ko-g34-u10.w.6":"desenhar","ko-g34-u10.w.7":"descansar","ko-g34-u10.w.8":"tirar (uma foto)","ko-g34-u10.w.9":"cantar","ko-g34-u10.s.0":"Eu brinco no pátio da escola.","ko-g34-u10.s.1":"Eu como macarrão frio num restaurante.","ko-g34-u10.s.2":"Eu leio livros na biblioteca.","ko-g34-u10.s.3":"Eu faço um castelo de areia na praia.","ko-g34-u10.s.4":"Eu descanso em casa.","ko-g34-u10.s.5":"Eu desenho no parque.","ko-g34-u10.s.6":"Eu pulo corda no ginásio.","ko-g34-u10.s.7":"Onde a gente se encontra?","ko-g34-u10.g.title":"Onde a ação acontece: 에서","ko-g34-u10.g.x.0":"Use 에서 depois do lugar onde você faz alguma coisa: 식당에서 먹어요 (eu como num restaurante).","ko-g34-u10.g.x.1":"Use 에 com 가요, 와요 e 있어요: 식당에 가요, 식당에 있어요.","ko-g34-u10.g.x.2":"Teste rápido: se alguém está fazendo uma ação ali, é 에서.","ko-g34-u10.g.0":"Eu como num restaurante.","ko-g34-u10.g.1":"Eu jogo futebol no pátio da escola.","ko-g34-u10.g.2":"Eu tomo suco num café.","ko-g34-u10.g.3":"Eu vou à biblioteca.","ko-g34-u10.g.4":"Meu irmão mais velho está no quarto dele.","ko-g34-u10.g.5":"Eu tiro fotos na praia.","ko-g34-u10.g.5.task":"Troque 공원 (parque) por 바닷가 (praia).","ko-g34-u10.g.6":"Eu brinco em casa com meu amigo.","ko-g34-u10.g.6.task":'Mude para "brincar em casa": use 에서 e 놀아요.',"ko-g34-u10.g.7":"Eu jogo basquete no ginásio.","ko-g34-u10.g.7.task":"Diga o que você faz lá: 농구를 해요 (jogar basquete).","ko-g34-u11.title":"Contando coisas","ko-g34-u11.tip":"O dinheiro usa outro conjunto de números (천 = 1.000): 삼천 원 são 3.000 wons. Para contar coisas, use 한, 두, 세, 네.","ko-g34-u11.w.0":"um (antes de um contador)","ko-g34-u11.w.1":"dois (antes de um contador)","ko-g34-u11.w.2":"três (antes de um contador)","ko-g34-u11.w.3":"quatro (antes de um contador)","ko-g34-u11.w.4":"pessoas (contador)","ko-g34-u11.w.5":"animais (contador)","ko-g34-u11.w.6":"livros (contador)","ko-g34-u11.w.7":"folhas (contador)","ko-g34-u11.w.8":"anos de idade (contador)","ko-g34-u11.w.9":"quantos","ko-g34-u11.s.0":"Uma maçã, por favor.","ko-g34-u11.s.1":"Na minha família somos quatro.","ko-g34-u11.s.2":"Tem dois gatos.","ko-g34-u11.s.3":"Quantos anos você tem?","ko-g34-u11.s.4":"Eu tenho nove anos.","ko-g34-u11.s.5":"Eu leio três livros.","ko-g34-u11.s.6":"Uma folha de papel, por favor.","ko-g34-u11.s.7":"Tem dez alunos.","ko-g34-u11.g.title":"Contar: número + palavra contadora","ko-g34-u11.g.x.0":"O coreano conta com uma palavra contadora depois do número: 사과 두 개 (duas maçãs), 학생 세 명 (três alunos).","ko-g34-u11.g.x.1":"하나, 둘, 셋, 넷 ficam mais curtos antes de um contador: 한, 두, 세, 네.","ko-g34-u11.g.x.2":"Contadores: 개 coisas, 명 pessoas, 마리 animais, 권 livros, 장 folhas de papel, 살 anos de idade.","ko-g34-u11.g.0":"Duas maçãs, por favor.","ko-g34-u11.g.1":"Tem três alunos.","ko-g34-u11.g.2":"Tem um cachorrinho.","ko-g34-u11.g.3":"Eu tenho oito anos.","ko-g34-u11.g.4":"Tem quatro livros.","ko-g34-u11.g.5":"Tem três gatos.","ko-g34-u11.g.5.task":"Faça ficarem três gatos.","ko-g34-u11.g.6":"Duas folhas de papel, por favor.","ko-g34-u11.g.6.task":"Peça duas folhas.","ko-g34-u11.g.7":"Quatro amigos estão vindo.","ko-g34-u11.g.7.task":"Faça ficarem quatro amigos.","ko-g34-u11.st.title":"Na padaria","ko-g34-u11.st.l.0":"Olá! Dois pães, por favor.","ko-g34-u11.st.l.1":"Qual pão?","ko-g34-u11.st.l.2":"Um destes pães de creme e um daqueles pães de chocolate.","ko-g34-u11.st.l.3":"Aqui está. São 3.000 wons.","ko-g34-u11.st.l.4":"Um leite também, por favor.","ko-g34-u11.st.l.5":"Certo, são 4.000 wons no total.","ko-g34-u11.st.q.0":"Quantos pães a Seoyeon compra?","ko-g34-u11.st.q.0.o.0":"두 개","ko-g34-u11.st.q.0.o.1":"세 개","ko-g34-u11.st.q.0.o.2":"한 개","ko-g34-u11.st.q.1":"O que mais ela compra?","ko-g34-u11.st.q.1.o.0":"우유","ko-g34-u11.st.q.1.o.1":"주스","ko-g34-u11.st.q.1.o.2":"케이크","ko-g34-u12.title":"Que horas são?","ko-g34-u12.tip":"As horas usam 한, 두, 세 (os números de contar), mas os minutos usam 일, 이, 삼 (os outros números). Então 3h10 é 세 시 십 분.","ko-g34-u12.w.0":"hora (em ponto)","ko-g34-u12.w.1":"minuto","ko-g34-u12.w.2":"e meia","ko-g34-u12.w.3":"agora","ko-g34-u12.w.4":"manhã (a.m.)","ko-g34-u12.w.5":"tarde (p.m.)","ko-g34-u12.w.6":"almoço","ko-g34-u12.w.7":"noite, jantar","ko-g34-u12.w.8":"cedo","ko-g34-u12.w.9":"tarde (atrasado)","ko-g34-u12.s.0":"Que horas são agora?","ko-g34-u12.s.1":"É uma hora.","ko-g34-u12.s.2":"Vamos nos encontrar às duas e meia.","ko-g34-u12.s.3":"Eu vou para a escola às oito da manhã.","ko-g34-u12.s.4":"Eu almoço à uma.","ko-g34-u12.s.5":"Vamos nos encontrar às quatro da tarde.","ko-g34-u12.s.6":"Eu faço a lição de casa à noite.","ko-g34-u12.s.7":"Hoje eu vou dormir tarde.","ko-g34-u12.g.title":"Dizer as horas: 몇 시예요?","ko-g34-u12.g.x.0":"Diga a hora com os números curtos de contar + 시: 한 시, 두 시, 세 시, 열두 시.","ko-g34-u12.g.x.1":'"E meia" é 반: 두 시 반 (2h30). Os minutos usam o outro conjunto de números: 오 분, 십 분.',"ko-g34-u12.g.x.2":'Acrescente 에 para dizer "às": 일곱 시에 일어나요 (eu acordo às sete).',"ko-g34-u12.g.0":"Agora é uma hora.","ko-g34-u12.g.1":"São três e meia.","ko-g34-u12.g.2":"Eu acordo às sete.","ko-g34-u12.g.3":"Eu almoço ao meio-dia.","ko-g34-u12.g.4":"Que horas a gente se encontra?","ko-g34-u12.g.5":"Eu volto para casa às quatro.","ko-g34-u12.g.5.task":"Mude a hora para quatro em ponto.","ko-g34-u12.g.6":"São cinco e meia.","ko-g34-u12.g.6.task":"Acrescente meia hora: use 반.","ko-g34-u12.g.7":"Eu vou dormir às nove.","ko-g34-u12.g.7.task":"Diga que você vai dormir às nove: use 에 e 자요.","ko-g34-u13.title":"Quem? Onde? Quando? Por quê?","ko-g34-u13.tip":"A pergunta mais útil numa loja coreana: 이거 얼마예요? (Quanto custa isto?) Experimente numa lojinha de mentira em casa!","ko-g34-u13.w.0":"quem","ko-g34-u13.w.1":"onde","ko-g34-u13.w.2":"quando","ko-g34-u13.w.3":"por quê","ko-g34-u13.w.4":"como","ko-g34-u13.w.5":"que tipo de","ko-g34-u13.w.6":"quanto (custa)","ko-g34-u13.w.7":"qual","ko-g34-u13.w.8":"motivo","ko-g34-u13.w.9":"resposta","ko-g34-u13.s.0":"Quem é aquela pessoa?","ko-g34-u13.s.1":"Quando são as férias?","ko-g34-u13.s.2":"Por que você está triste?","ko-g34-u13.s.3":"Como eu chego à biblioteca?","ko-g34-u13.s.4":"Quanto custa isto?","ko-g34-u13.s.5":"De que comida você gosta?","ko-g34-u13.s.6":"De que país você é?","ko-g34-u13.s.7":"Onde fica o banheiro?","ko-g34-u13.g.title":"Palavras de pergunta: 누구, 어디, 언제, 왜, 어떻게, 얼마","ko-g34-u13.g.x.0":"누구 quem · 뭐 o quê · 어디 onde · 언제 quando · 왜 por quê · 어떻게 como · 얼마 quanto.","ko-g34-u13.g.x.1":"Com 이에요/예요 elas vêm no final: 누구예요? 어디예요? 얼마예요?","ko-g34-u13.g.x.2":"Com outros verbos elas vêm antes do verbo: 어디에 가요? 왜 울어요?","ko-g34-u13.g.0":"Quem é esta pessoa?","ko-g34-u13.g.1":"Quando é o seu aniversário?","ko-g34-u13.g.2":"Por que você está chorando?","ko-g34-u13.g.3":"Quanto custa esta maçã?","ko-g34-u13.g.4":"Como você vai para a escola?","ko-g34-u13.g.5":"Aonde você vai?","ko-g34-u13.g.5.task":'Pergunte "aonde": use 어디에.',"ko-g34-u13.g.6":"Quando você vem?","ko-g34-u13.g.6.task":'Pergunte "quando": use 언제.',"ko-g34-u13.g.7":"Quem é aquela pessoa?","ko-g34-u13.g.7.task":'Pergunte "quem": use 누구예요.',"ko-g34-u14.title":"Eu quero…","ko-g34-u14.tip":"O que VOCÊ quer fazer? Faça três frases com -고 싶어요 sobre este fim de semana.","ko-g34-u14.w.0":"sonho","ko-g34-u14.w.1":"cientista","ko-g34-u14.w.2":"pintor","ko-g34-u14.w.3":"atleta, jogador","ko-g34-u14.w.4":"espaço sideral","ko-g34-u14.w.5":"parque de diversões","ko-g34-u14.w.6":"tteokbokki (bolinhos de arroz apimentados)","ko-g34-u14.w.7":"criar (um bicho, uma planta)","ko-g34-u14.w.8":"voar","ko-g34-u14.w.9":"boneco de neve","ko-g34-u14.s.0":"Eu quero ser cientista.","ko-g34-u14.s.1":"Eu quero ir para o espaço.","ko-g34-u14.s.2":"Eu quero comer tteokbokki.","ko-g34-u14.s.3":"Eu quero criar um gato.","ko-g34-u14.s.4":"Eu quero ir a um parque de diversões.","ko-g34-u14.s.5":"O que você quer fazer neste fim de semana?","ko-g34-u14.s.6":"Hoje eu quero descansar.","ko-g34-u14.s.7":"Meu sonho é ser pintor.","ko-g34-u14.g.title":"Querer fazer algo: -고 싶어요","ko-g34-u14.g.x.0":"Para dizer que você quer fazer algo, tire o 다 e acrescente 고 싶어요: 먹다 → 먹고 싶어요 (eu quero comer).","ko-g34-u14.g.x.1":"Funciona do mesmo jeito com todos os verbos, com ou sem letra embaixo: 가고 싶어요, 놀고 싶어요, 쉬고 싶어요.","ko-g34-u14.g.x.2":'"Quero ser" é 되고 싶어요: 의사가 되고 싶어요 (eu quero ser médico).',"ko-g34-u14.g.0":"Eu quero comer pizza.","ko-g34-u14.g.1":"Eu quero ir para a praia.","ko-g34-u14.g.2":"Eu quero ser pintor.","ko-g34-u14.g.3":"Eu quero brincar com meu amigo.","ko-g34-u14.g.4":"O que você quer fazer?","ko-g34-u14.g.5":"Eu quero ir para o espaço.","ko-g34-u14.g.5.task":"Diga que você quer: use -고 싶어요.","ko-g34-u14.g.6":"Eu quero criar um cachorrinho.","ko-g34-u14.g.6.task":"Diga que você quer: use -고 싶어요.","ko-g34-u14.g.7":"Eu quero fazer um boneco de neve.","ko-g34-u14.g.7.task":"Diga que você quer: use -고 싶어요.","ko-g34-u14.st.title":"Meu sonho","ko-g34-u14.st.l.0":"Pessoal, qual é o sonho de vocês?","ko-g34-u14.st.l.1":"Eu quero ser jogador de futebol!","ko-g34-u14.st.l.2":"Eu quero ser cientista. Quero ir para o espaço.","ko-g34-u14.st.l.3":"Eu quero ser pintora.","ko-g34-u14.st.l.4":"Todos são sonhos maravilhosos!","ko-g34-u14.st.q.0":"O que a Seoyeon quer ser?","ko-g34-u14.st.q.0.o.0":"과학자","ko-g34-u14.st.q.0.o.1":"화가","ko-g34-u14.st.q.0.o.2":"축구 선수","ko-g34-u14.st.q.1":"Quem quer ser pintora?","ko-g34-u14.st.q.1.o.0":"지우","ko-g34-u14.st.q.1.o.1":"민준","ko-g34-u14.st.q.1.o.2":"서연","ko-g34-u15.title":"Gosto e não gosto","ko-g34-u15.tip":'Faça uma lista de "gosto / não gosto" com a sua família: 아빠는 커피를 좋아해요. 저는 벌레를 싫어해요!',"ko-g34-u15.w.0":"gostar","ko-g34-u15.w.1":"não gostar","ko-g34-u15.w.2":"cenoura","ko-g34-u15.w.3":"legumes","ko-g34-u15.w.4":"pimenta","ko-g34-u15.w.5":"chocolate","ko-g34-u15.w.6":"conto de fadas","ko-g34-u15.w.7":"desenho animado, gibi","ko-g34-u15.w.8":"inseto","ko-g34-u15.w.9":"o que mais","ko-g34-u15.s.0":"Eu gosto de chocolate.","ko-g34-u15.s.1":"O papai gosta de cenoura.","ko-g34-u15.s.2":"De que contos de fadas você gosta?","ko-g34-u15.s.3":"Minha irmã mais velha tem medo de insetos.","ko-g34-u15.s.4":"Meu irmão mais velho gosta de contos de fadas.","ko-g34-u15.s.5":"O que eu mais gosto é melancia.","ko-g34-u15.s.6":"Eu também gosto de legumes.","ko-g34-u15.s.7":"A pimenta é apimentada demais.","ko-g34-u15.g.title":"Gostos: 좋아해요 · 싫어해요","ko-g34-u15.g.x.0":"Use 을/를 좋아해요 para as coisas de que você gosta: 사과를 좋아해요.","ko-g34-u15.g.x.1":"Use 을/를 싫어해요 para as coisas de que você não gosta: 벌레를 싫어해요.","ko-g34-u15.g.x.2":'좋아요 também quer dizer "eu gosto": 이 노래가 좋아요. Com 좋아요, use 이/가 em vez de 을/를.',"ko-g34-u15.g.0":"Eu gosto de gatos.","ko-g34-u15.g.1":"Meu irmãozinho detesta cenoura.","ko-g34-u15.g.2":"Eu gosto de chocolate.","ko-g34-u15.g.3":"Eu gosto desta música.","ko-g34-u15.g.4":"De que desenhos animados você gosta?","ko-g34-u15.g.5":"Eu não gosto de insetos.","ko-g34-u15.g.5.task":"Diga que você não gosta.","ko-g34-u15.g.6":"Meu irmão mais velho gosta de legumes.","ko-g34-u15.g.6.task":"Troque 고기 (carne) por 채소 (legumes).","ko-g34-u15.g.7":"O que eu mais gosto é morango.","ko-g34-u15.g.7.task":'Diga "o que mais": acrescente 제일.',"ko-g34-u16.title":"Ontem eu…: o passado","ko-g34-u16.tip":'Escute o som de ㅆ no passado: 갔어요, 봤어요, 했어요. Esse ㅆ é como um sinalzinho de "já aconteceu"!',"ko-g34-u16.w.0":"semana passada","ko-g34-u16.w.1":"agora há pouco","ko-g34-u16.w.2":"fiz","ko-g34-u16.w.3":"fui","ko-g34-u16.w.4":"comi","ko-g34-u16.w.5":"vi","ko-g34-u16.w.6":"vim","ko-g34-u16.w.7":"dormi","ko-g34-u16.w.8":"foi divertido","ko-g34-u16.w.9":"férias escolares","ko-g34-u16.s.0":"Ontem eu assisti a um filme.","ko-g34-u16.s.1":"De manhã eu comi pão.","ko-g34-u16.s.2":"Semana passada eu fui a Busan.","ko-g34-u16.s.3":"Eu terminei toda a lição de casa.","ko-g34-u16.s.4":"Meu amigo veio à minha casa.","ko-g34-u16.s.5":"Ontem à noite eu dormi cedo.","ko-g34-u16.s.6":"As férias foram muito divertidas.","ko-g34-u16.s.7":"Agora há pouco eu encontrei a mamãe.","ko-g34-u16.g.title":"O passado: -았어요 / -었어요 / 했어요","ko-g34-u16.g.x.0":"Para o passado, mude a terminação com 요: 가요 → 갔어요, 먹어요 → 먹었어요.","ko-g34-u16.g.x.1":"Verbos cuja última vogal é ㅏ ou ㅗ ganham 았어요 (놀다 → 놀았어요, 보다 → 봤어요). Os outros ganham 었어요 (먹다 → 먹었어요).","ko-g34-u16.g.x.2":"Os verbos em 하다 viram 했어요: 공부하다 → 공부했어요.","ko-g34-u16.g.0":"Ontem eu fui ao parque.","ko-g34-u16.g.1":"Eu tomei café da manhã.","ko-g34-u16.g.2":"Eu assisti a um filme.","ko-g34-u16.g.3":"Eu fiz a lição de casa.","ko-g34-u16.g.4":"Eu brinquei com meu amigo.","ko-g34-u16.g.5":"Eu li um livro.","ko-g34-u16.g.5.task":"Passe para o passado.","ko-g34-u16.g.6":"Meu irmãozinho foi dormir cedo.","ko-g34-u16.g.6.task":"Passe para o passado.","ko-g34-u16.g.7":"O papai cozinhou.","ko-g34-u16.g.7.task":"Passe para o passado.","ko-g34-u16.st.title":"Como foram as férias?","ko-g34-u16.st.l.0":"Você aproveitou as férias?","ko-g34-u16.st.l.1":"Sim! Eu fui para a ilha de Jeju.","ko-g34-u16.st.l.2":"Uau, o que você fez em Jeju?","ko-g34-u16.st.l.3":"Eu nadei no mar. Também comi um monte de tangerinas.","ko-g34-u16.st.l.4":"Eu fiquei na casa da minha avó. Brinquei com o cachorrinho.","ko-g34-u16.st.l.5":"As férias foram muito divertidas!","ko-g34-u16.st.q.0":"Aonde o Hajun foi?","ko-g34-u16.st.q.0.o.0":"제주도","ko-g34-u16.st.q.0.o.1":"서울","ko-g34-u16.st.q.0.o.2":"할머니 집","ko-g34-u16.st.q.1":"Com o que a Jiwoo brincou?","ko-g34-u16.st.q.1.o.0":"강아지","ko-g34-u16.st.q.1.o.1":"고양이","ko-g34-u16.st.q.1.o.2":"공","ko-g34-u17.title":"Eu vou…: o futuro","ko-g34-u17.tip":"Passado, presente, futuro: 갔어요 (fui) → 가요 (vou) → 갈 거예요 (irei). Diga os três para 먹다 e 하다!","ko-g34-u17.w.0":"semana que vem","ko-g34-u17.w.1":"ano que vem","ko-g34-u17.w.2":"plano","ko-g34-u17.w.3":"prova","ko-g34-u17.w.4":"acampamento","ko-g34-u17.w.5":"barraca","ko-g34-u17.w.6":"treino","ko-g34-u17.w.7":"mudança","ko-g34-u17.w.8":"provavelmente","ko-g34-u17.w.9":"logo","ko-g34-u17.s.0":"Amanhã eu vou acampar.","ko-g34-u17.s.1":"No fim de semana eu vou treinar piano.","ko-g34-u17.s.2":"Provavelmente vai chover.","ko-g34-u17.s.3":"Semana que vem tem prova.","ko-g34-u17.s.4":"Eu vou dormir numa barraca.","ko-g34-u17.s.5":"Logo a gente vai jantar.","ko-g34-u17.s.6":"Ano que vem eu vou fazer dez anos.","ko-g34-u17.s.7":"O que você vai fazer nas férias?","ko-g34-u17.g.title":"O futuro: -(으)ㄹ 거예요","ko-g34-u17.g.x.0":"Para falar do futuro, tire o 다 e acrescente ㄹ 거예요: 가다 → 갈 거예요, 하다 → 할 거예요.","ko-g34-u17.g.x.1":"Se o radical termina com uma letra embaixo, acrescente 을 거예요: 먹다 → 먹을 거예요, 읽다 → 읽을 거예요.","ko-g34-u17.g.x.2":'Também pode querer dizer "provavelmente": 비가 올 거예요 (provavelmente vai chover).',"ko-g34-u17.g.0":"Amanhã eu vou ao parque.","ko-g34-u17.g.1":"No jantar eu vou comer pizza.","ko-g34-u17.g.2":"No fim de semana eu vou estudar.","ko-g34-u17.g.3":"Provavelmente vai nevar.","ko-g34-u17.g.4":"Eu vou ler um livro.","ko-g34-u17.g.5":"Amanhã eu vou encontrar meu amigo.","ko-g34-u17.g.5.task":"Mude para amanhã: use 내일 e -ㄹ 거예요.","ko-g34-u17.g.6":"Eu vou acampar.","ko-g34-u17.g.6.task":"Passe para o futuro.","ko-g34-u17.g.7":"Nas férias eu vou aprender a nadar.","ko-g34-u17.g.7.task":"Passe para o futuro.","ko-g34-u18.title":"E, com, também","ko-g34-u18.tip":"Conte sua rotina da manhã como uma corrente comprida: 일어나고, 씻고, 옷을 입고, 학교에 가요!","ko-g34-u18.w.0":"levantar","ko-g34-u18.w.1":"lavar-se","ko-g34-u18.w.2":"vestir (roupa)","ko-g34-u18.w.3":"escovar os dentes","ko-g34-u18.w.4":"arrumar","ko-g34-u18.w.5":"tomar banho","ko-g34-u18.w.6":"e (depois)","ko-g34-u18.w.7":"e, com","ko-g34-u18.w.8":"também","ko-g34-u18.w.9":"juntos","ko-g34-u18.s.0":"Eu levanto e lavo o rosto.","ko-g34-u18.s.1":"Eu lavo as mãos e como.","ko-g34-u18.s.2":"Eu tomo leite e como uma maçã.","ko-g34-u18.s.3":"Eu também vou junto.","ko-g34-u18.s.4":"Eu calço as meias e saio.","ko-g34-u18.s.5":"Eu arrumo o quarto e descanso.","ko-g34-u18.s.6":"Eu vou ao parque com o papai.","ko-g34-u18.s.7":"Eu leio um livro e vou dormir.","ko-g34-u18.g.title":"E: -고 · 하고 · 도","ko-g34-u18.g.x.0":"Para juntar duas ações, tire o 다 e acrescente 고: 먹다 → 먹고. 밥을 먹고 양치해요 (eu como e escovo os dentes).","ko-g34-u18.g.x.1":'Para juntar dois substantivos, use 하고: 빵하고 우유 (pão e leite). 하고 também quer dizer "com": 엄마하고 가요.',"ko-g34-u18.g.x.2":'도 quer dizer "também" e fica no lugar de 은/는, 이/가 ou 을/를: 저도 좋아요 (eu também gosto).',"ko-g34-u18.g.0":"Eu como e depois escovo os dentes.","ko-g34-u18.g.1":"Eu me visto e vou para a escola.","ko-g34-u18.g.2":"Eu como pão e tomo leite.","ko-g34-u18.g.3":"Eu também quero ir.","ko-g34-u18.g.4":"Eu vou à feira com a mamãe.","ko-g34-u18.g.5":"Eu faço a lição de casa e depois brinco.","ko-g34-u18.g.5.task":"Junte as duas frases com -고.","ko-g34-u18.g.6":"Eu tomo banho e depois vou dormir.","ko-g34-u18.g.6.task":"Junte as duas frases com -고.","ko-g34-u18.g.7":"Meu irmãozinho também vem.","ko-g34-u18.g.7.task":'Diga "também": use 도.',"ko-g34-u19.title":"Por favor…","ko-g34-u19.tip":"Duas frases mágicas para a Coreia: 주세요 (me dê, por favor) e 천천히 말해 주세요 (fale devagar, por favor). Diga com um sorriso!","ko-g34-u19.w.0":"me dê, por favor","ko-g34-u19.w.1":"por favor (suaviza um pedido)","ko-g34-u19.w.2":"sente-se, por favor","ko-g34-u19.w.3":"venha, por favor","ko-g34-u19.w.4":"espere, por favor","ko-g34-u19.w.5":"em silêncio","ko-g34-u19.w.6":"devagar","ko-g34-u19.w.7":"de novo","ko-g34-u19.w.8":"um momento","ko-g34-u19.w.9":"me ajude, por favor","ko-g34-u19.s.0":"Um copo de leite, por favor.","ko-g34-u19.s.1":"Sente-se, por favor.","ko-g34-u19.s.2":"Seja bem-vindo, pode entrar.","ko-g34-u19.s.3":"Espere aqui, por favor.","ko-g34-u19.s.4":"Vá um pouco mais devagar, por favor.","ko-g34-u19.s.5":"Diga mais uma vez, por favor.","ko-g34-u19.s.6":"Façam silêncio na biblioteca, por favor.","ko-g34-u19.s.7":"Me ajude, por favor!","ko-g34-u19.g.title":"Pedir com educação: -(으)세요 · -아/어 주세요","ko-g34-u19.g.x.0":"Para pedir com educação que alguém faça algo, tire o 다 e acrescente 세요: 가다 → 가세요, 오다 → 오세요.","ko-g34-u19.g.x.1":"Se o radical termina com uma letra embaixo, acrescente 으세요: 앉다 → 앉으세요, 읽다 → 읽으세요.","ko-g34-u19.g.x.2":"Para pedir um favor para você, use -아/어 주세요: 도와주세요 (me ajude, por favor), 말해 주세요 (me diga, por favor).","ko-g34-u19.g.0":"Sente-se aqui, por favor.","ko-g34-u19.g.1":"Venha por aqui, por favor.","ko-g34-u19.g.2":"Leia este livro, por favor.","ko-g34-u19.g.3":"Fale devagar, por favor.","ko-g34-u19.g.4":"Um pouco de água, por favor.","ko-g34-u19.g.5":"Espere um momento, por favor.","ko-g34-u19.g.5.task":"Transforme em pedido educado: use -세요.","ko-g34-u19.g.6":"Lave as mãos, por favor.","ko-g34-u19.g.6.task":"Transforme em pedido educado: use -으세요.","ko-g34-u19.g.7":"Diga de novo, por favor.","ko-g34-u19.g.7.task":"Peça um favor: use 주세요.","ko-g34-u19.st.title":"No restaurante","ko-g34-u19.st.l.0":"Bem-vindos! Quantas pessoas?","ko-g34-u19.st.l.1":"Três pessoas.","ko-g34-u19.st.l.2":"Venham por aqui, por favor. Sentem-se aqui.","ko-g34-u19.st.l.3":"Um bibimbap e dois gimbaps, por favor.","ko-g34-u19.st.l.4":"Certo, esperem um momento, por favor.","ko-g34-u19.st.l.5":"Um pouco de água também, por favor!","ko-g34-u19.st.q.0":"Quantas pessoas há na família?","ko-g34-u19.st.q.0.o.0":"세 명","ko-g34-u19.st.q.0.o.1":"두 명","ko-g34-u19.st.q.0.o.2":"네 명","ko-g34-u19.st.q.1":"O que a Seoyeon pede?","ko-g34-u19.st.q.1.o.0":"비빔밥하고 김밥","ko-g34-u19.st.q.1.o.1":"떡볶이하고 라면","ko-g34-u19.st.q.1.o.2":"김밥 세 개","ko-g34-u20.title":"Muito, um pouco, demais","ko-g34-u20.tip":"Brinque de opostos: uma pessoa diz 커요! e a outra responde 작아요! Depois tentem 빨라요 → 느려요.","ko-g34-u20.w.0":"grande","ko-g34-u20.w.1":"pequeno","ko-g34-u20.w.2":"comprido","ko-g34-u20.w.3":"curto","ko-g34-u20.w.4":"pesado","ko-g34-u20.w.5":"leve (não pesado)","ko-g34-u20.w.6":"rápido","ko-g34-u20.w.7":"lento","ko-g34-u20.w.8":"muito","ko-g34-u20.w.9":"demais","ko-g34-u20.s.0":"As baleias são muito grandes.","ko-g34-u20.s.1":"Os ratos são muito pequenos.","ko-g34-u20.s.2":"Este livro é um pouco pesado.","ko-g34-u20.s.3":"As tartarugas são muito lentas.","ko-g34-u20.s.4":"O trem é rápido demais.","ko-g34-u20.s.5":"Os balões são leves.","ko-g34-u20.s.6":"O cabelo do meu irmãozinho é comprido.","ko-g34-u20.s.7":"Este lápis é curto demais.","ko-g34-u20.g.title":"Muito, um pouco, demais: 아주 · 조금 · 너무","ko-g34-u20.g.x.0":"As palavras que descrevem já funcionam como verbos: 커요 (é grande), 빨라요 (é rápido).","ko-g34-u20.g.x.1":"Coloque 아주 (muito), 조금 (um pouco) ou 너무 (demais) logo antes delas: 아주 커요, 조금 작아요, 너무 무거워요.","ko-g34-u20.g.x.2":"Aprenda em pares: 커요 ↔ 작아요, 길어요 ↔ 짧아요, 빨라요 ↔ 느려요, 무거워요 ↔ 가벼워요.","ko-g34-u20.g.0":"Os elefantes são muito grandes.","ko-g34-u20.g.1":"A mochila é pesada demais.","ko-g34-u20.g.2":"Os caracóis são lentos.","ko-g34-u20.g.3":"Meu cabelo é um pouco curto.","ko-g34-u20.g.4":"Os guepardos são muito rápidos.","ko-g34-u20.g.5":"Esta calça é comprida demais.","ko-g34-u20.g.5.task":'Diga "comprida demais": acrescente 너무.',"ko-g34-u20.g.6":"As formigas são muito pequenas.","ko-g34-u20.g.6.task":"Mude para o oposto.","ko-g34-u20.g.7":"As penas são muito leves.","ko-g34-u20.g.7.task":'Diga "muito leves": acrescente 아주.'},s={"ko-g56-u01.title":"Agora mesmo: -고 있어요","ko-g56-u01.tip":"Olhe em volta e descreva o que cada um está fazendo agora: 아빠는 요리하고 있어요. 고양이는 자고 있어요.","ko-g56-u01.w.0":"ultimamente","ko-g56-u01.w.1":"violão","ko-g56-u01.w.2":"ligação","ko-g56-u01.w.3":"se arrumar","ko-g56-u01.w.4":"um passeio","ko-g56-u01.w.5":"soneca","ko-g56-u01.w.6":"roupa para lavar","ko-g56-u01.w.7":"mensagem de texto","ko-g56-u01.w.8":"enviar","ko-g56-u01.w.9":"procurar","ko-g56-u01.w.10":"fazer, criar","ko-g56-u01.w.11":"rir, sorrir","ko-g56-u01.s.0":"O que você está fazendo agora?","ko-g56-u01.s.1":"Meu irmãozinho está tirando uma soneca.","ko-g56-u01.s.2":"A mamãe está no telefone.","ko-g56-u01.s.3":"Ultimamente estou aprendendo violão.","ko-g56-u01.s.4":"O papai está lavando a roupa.","ko-g56-u01.s.5":"Meu irmão mais velho está ligando para um amigo.","ko-g56-u01.s.6":"A vovó está passeando com o cachorrinho.","ko-g56-u01.s.7":"Estou me arrumando para a escola.","ko-g56-u01.g.title":"Acontecendo agora: -고 있어요","ko-g56-u01.g.x.0":"Para dizer que algo está acontecendo agora, tire o 다 e acrescente 고 있어요: 먹다 → 먹고 있어요 (estou comendo).","ko-g56-u01.g.x.1":"Também serve para coisas que você anda fazendo ultimamente: 요즘 기타를 배우고 있어요.","ko-g56-u01.g.x.2":"Para o passado, use 고 있었어요: 그때 자고 있었어요 (naquela hora eu estava dormindo).","ko-g56-u01.g.0":"Estou comendo agora.","ko-g56-u01.g.1":"O bebê está tirando uma soneca.","ko-g56-u01.g.2":"Meu irmão mais velho está tocando violão.","ko-g56-u01.g.3":"O que você está fazendo?","ko-g56-u01.g.4":"Naquela hora eu estava lendo um livro.","ko-g56-u01.g.5":"A mamãe está lavando a roupa.","ko-g56-u01.g.5.task":"Diga que está acontecendo agora: use -고 있어요.","ko-g56-u01.g.6":"Estou mandando uma mensagem para o meu amigo.","ko-g56-u01.g.6.task":"Diga que está acontecendo agora: use -고 있어요.","ko-g56-u01.g.7":"Ultimamente estou aprendendo a nadar.","ko-g56-u01.g.7.task":"Diga que você anda fazendo isso: use -고 있어요.","ko-g56-u02.title":"Conseguir e não conseguir","ko-g56-u02.tip":"Você está lendo hangul agora mesmo — as letras que o rei Sejong criou para que todo mundo pudesse ler. Muito legal!","ko-g56-u02.w.0":"hangul (o alfabeto coreano)","ko-g56-u02.w.1":"letra, caractere","ko-g56-u02.w.2":"som","ko-g56-u02.w.3":"forma","ko-g56-u02.w.4":"rei","ko-g56-u02.w.5":"o povo comum (palavra antiga)","ko-g56-u02.w.6":"facilmente","ko-g56-u02.w.7":"dirigir","ko-g56-u02.w.8":"assobio","ko-g56-u02.w.9":"língua estrangeira","ko-g56-u02.w.10":"criou","ko-g56-u02.w.11":"esperto","ko-g56-u02.s.0":"Meu irmãozinho consegue ler um pouco de hangul.","ko-g56-u02.s.1":"Meu irmãozinho ainda não sabe andar de bicicleta.","ko-g56-u02.s.2":"A mamãe não sabe dirigir.","ko-g56-u02.s.3":"Meu irmão mais velho assobia muito bem.","ko-g56-u02.s.4":"Está chovendo, então não posso brincar lá fora.","ko-g56-u02.s.5":"Meu irmão mais velho sabe falar duas línguas estrangeiras.","ko-g56-u02.s.6":"Dá para aprender hangul facilmente.","ko-g56-u02.s.7":"Dá para ler esta letra facilmente.","ko-g56-u02.g.title":"Conseguir e não conseguir: -(으)ㄹ 수 있어요 / 없어요","ko-g56-u02.g.x.0":"Para dizer que você consegue fazer algo, tire o 다 e acrescente ㄹ 수 있어요: 가다 → 갈 수 있어요, 하다 → 할 수 있어요.","ko-g56-u02.g.x.1":"Depois de uma letra embaixo, acrescente 을 수 있어요: 읽다 → 읽을 수 있어요. Radicais que terminam em ㄹ não mudam: 놀다 → 놀 수 있어요.","ko-g56-u02.g.x.2":'Para "não consigo", troque 있어요 por 없어요: 갈 수 없어요. Você também pode colocar 못 antes do verbo: 못 가요.',"ko-g56-u02.g.0":"Eu consigo ler hangul.","ko-g56-u02.g.1":"O papai sabe dirigir.","ko-g56-u02.g.2":"Hoje eu não posso brincar.","ko-g56-u02.g.3":"Você sabe assobiar?","ko-g56-u02.g.4":"Eu não sei nadar.","ko-g56-u02.g.5":"Meu irmãozinho não sabe andar de bicicleta.","ko-g56-u02.g.5.task":'Diga "não consegue": use 없어요.',"ko-g56-u02.g.6":"Meu irmão mais velho sabe falar uma língua estrangeira.","ko-g56-u02.g.6.task":"Diga que ele consegue: use -ㄹ 수 있어요.","ko-g56-u02.g.7":"Você consegue ler esta letra?","ko-g56-u02.g.7.task":'Pergunte "você consegue": use -을 수 있어요.',"ko-g56-u02.r.ko":"O segredo do hangul","ko-g56-u02.r.genre":"História","ko-g56-u02.r.p.0":"Muito tempo atrás, os coreanos escreviam com caracteres chineses. Eram muitíssimos caracteres, e eram difíceis. Por isso, muita gente comum não sabia ler.","ko-g56-u02.r.p.1":"O rei Sejong, de Joseon, amava o seu povo. Por isso, em 1443, ele criou letras fáceis. Essas letras são o hangul.","ko-g56-u02.r.p.2":"As consoantes foram criadas olhando a forma da boca e da língua ao fazer cada som. Por exemplo, o ㄱ mostra a parte de trás da língua fechando a garganta. As vogais foram criadas a partir do céu, da terra e das pessoas.","ko-g56-u02.r.p.3":"Com apenas 24 letras, o hangul consegue escrever quase qualquer som. Por isso, qualquer pessoa aprende a ler em poucos dias. No dia 9 de outubro, o Dia do Hangul, os coreanos celebram essas letras.","ko-g56-u02.r.q.3.o.0":"a gente comum","ko-g56-u02.r.q.3.o.1":"os reis","ko-g56-u02.r.q.3.o.2":"os professores","ko-g56-u03.title":"Ter que: -아야 해요","ko-g56-u03.tip":"As crianças coreanas aprendem esta regra de trânsito: na faixa de pedestres, pare, olhe para a esquerda e para a direita, e levante a mão ao atravessar.","ko-g56-u03.w.0":"regra","ko-g56-u03.w.1":"cumprir (uma regra)","ko-g56-u03.w.2":"segurança","ko-g56-u03.w.3":"capacete","ko-g56-u03.w.4":"atravessar","ko-g56-u03.w.5":"semáforo","ko-g56-u03.w.6":"faixa de pedestres","ko-g56-u03.w.7":"fila","ko-g56-u03.w.8":"vez","ko-g56-u03.w.9":"importante","ko-g56-u03.w.10":"bem limpinho","ko-g56-u03.w.11":"sem falta","ko-g56-u03.s.0":"Você tem que lavar bem as mãos.","ko-g56-u03.s.1":"Você tem que atravessar na faixa de pedestres.","ko-g56-u03.s.2":"Quando andar de bicicleta, você tem que usar capacete.","ko-g56-u03.s.3":"No refeitório, a gente faz fila.","ko-g56-u03.s.4":"Amanhã eu tenho que ir cedo para a escola.","ko-g56-u03.s.5":"Primeiro eu tenho que fazer a lição de casa.","ko-g56-u03.s.6":"Todo mundo cumpre as regras.","ko-g56-u03.s.7":"Quando o sinal estiver verde, levante sempre a mão e atravesse.","ko-g56-u03.g.title":"Ter que: -아야 / -어야 해요","ko-g56-u03.g.x.0":"Para dizer que você tem que fazer algo, pegue a forma com 요, tire o 요 e acrescente 야 해요: 가요 → 가야 해요, 먹어요 → 먹어야 해요.","ko-g56-u03.g.x.1":"Os verbos em 하다 viram 해야 해요: 공부해야 해요 (eu tenho que estudar).","ko-g56-u03.g.x.2":"Para o passado, diga 해야 했어요: 어제 일찍 자야 했어요 (ontem eu tive que dormir cedo).","ko-g56-u03.g.0":"Você tem que lavar as mãos.","ko-g56-u03.g.1":"Agora eu tenho que ir.","ko-g56-u03.g.2":"Eu tenho que fazer a lição de casa.","ko-g56-u03.g.3":"Você tem que ficar na fila.","ko-g56-u03.g.4":"Você tem que usar capacete.","ko-g56-u03.g.5":"Amanhã eu tenho que acordar cedo.","ko-g56-u03.g.5.task":"Diga que você tem que fazer: use -아야 해요.","ko-g56-u03.g.6":"É preciso cumprir as regras da escola.","ko-g56-u03.g.6.task":"Diga que é preciso: use -어야 해요.","ko-g56-u03.g.7":"Ontem eu tive que estudar.","ko-g56-u03.g.7.task":"Mude para ontem (o passado).","ko-g56-u04.title":"Se, quando: -(으)면","ko-g56-u04.tip":'Faça frases com "se" sobre o seu dia: 숙제를 다 하면 게임을 해요. 비가 오면 집에서 놀아요.',"ko-g56-u04.w.0":"as quatro estações","ko-g56-u04.w.1":"bem marcado, nítido","ko-g56-u04.w.2":"flor de cerejeira","ko-g56-u04.w.3":"estação das chuvas","ko-g56-u04.w.4":"folhas de outono","ko-g56-u04.w.5":"guerra de bolas de neve","ko-g56-u04.w.6":"morno, quentinho","ko-g56-u04.w.7":"fresco, refrescante","ko-g56-u04.w.8":"se, supondo que","ko-g56-u04.w.9":"florescer","ko-g56-u04.w.10":"cair","ko-g56-u04.w.11":"acumular","ko-g56-u04.s.0":"Quando a neve se acumula, a gente anda de trenó.","ko-g56-u04.s.1":"Se o tempo estiver quentinho, eu vou ao parque.","ko-g56-u04.s.2":"Quando chega o verão, começa a estação das chuvas.","ko-g56-u04.s.3":"Se estiver com sede, beba água.","ko-g56-u04.s.4":"Quando chega o outono, as folhas caem.","ko-g56-u04.s.5":"Se não der tempo, vamos fazer amanhã.","ko-g56-u04.s.6":"Quando o vento está fresco, eu vou passear.","ko-g56-u04.s.7":"Se chover, a gente brinca em casa.","ko-g56-u04.g.title":"Se, quando: -(으)면","ko-g56-u04.g.x.0":'Tire o 다 e acrescente 면 para "se" ou "quando": 오다 → 오면. 비가 오면 우산을 써요 (se chover, eu uso guarda-chuva).',"ko-g56-u04.g.x.1":"Depois de uma letra embaixo, acrescente 으면: 있다 → 있으면, 먹다 → 먹으면.","ko-g56-u04.g.x.2":"Radicais que terminam em ㄹ só ganham 면: 놀다 → 놀면, 만들다 → 만들면.","ko-g56-u04.g.0":"Se chover, eu uso guarda-chuva.","ko-g56-u04.g.1":"Se você tiver tempo, vamos brincar.","ko-g56-u04.g.2":"Se estiver com fome, me avise.","ko-g56-u04.g.3":"Se estiver cansado, descanse.","ko-g56-u04.g.4":"Se você tomar este remédio, vai melhorar.","ko-g56-u04.g.5":"Quando chega a primavera, as cerejeiras florescem.","ko-g56-u04.g.5.task":"Junte com -면 (quando).","ko-g56-u04.g.6":"Quando neva, a gente faz guerra de bolas de neve.","ko-g56-u04.g.6.task":"Junte com -면 (quando).","ko-g56-u04.g.7":"Se eu me atrasar, eu ligo.","ko-g56-u04.g.7.task":"Junte com -으면 (se).","ko-g56-u04.r.ko":"As quatro estações da Coreia","ko-g56-u04.r.genre":"Cultura","ko-g56-u04.r.p.0":"A Coreia tem quatro estações bem marcadas. Primavera, verão, outono e inverno são todos diferentes. Quando chega a primavera, o tempo fica quentinho. Cerejeiras e forsítias florescem nas montanhas e nas ruas. As pessoas vão aos parques para ver as flores.","ko-g56-u04.r.p.1":"O verão é muito quente. Quando chega a estação das chuvas, chove muito. Quando a estação das chuvas termina, as crianças vão à praia ou à piscina.","ko-g56-u04.r.p.2":"No outono, o vento é fresco. As montanhas ficam lindas com folhas vermelhas e amarelas. O inverno é frio. Quando a neve se acumula, as crianças fazem bonecos de neve e guerra de bolas de neve.","ko-g56-u04.r.q.3.o.0":"folhas coloridas de outono","ko-g56-u04.r.q.3.o.1":"flores de cerejeira","ko-g56-u04.r.q.3.o.2":"bonecos de neve","ko-g56-u05.title":"Porque, então: -아서","ko-g56-u05.tip":'만나서 반가워요 (prazer em te conhecer) quer dizer, ao pé da letra, "como nos encontramos, estou contente" — agora você consegue ver o -아서 escondido aí dentro!',"ko-g56-u05.w.0":"perder a hora","ko-g56-u05.w.1":"atraso (para a escola)","ko-g56-u05.w.2":"febre","ko-g56-u05.w.3":"remédio","ko-g56-u05.w.4":"cair","ko-g56-u05.w.5":"se machucar","ko-g56-u05.w.6":"escorregadio","ko-g56-u05.w.7":"contente (de ver você)","ko-g56-u05.w.8":"se atrasou","ko-g56-u05.w.9":"perder (o ônibus)","ko-g56-u05.w.10":"então, por isso","ko-g56-u05.w.11":"porque","ko-g56-u05.s.0":"Peguei um resfriado, então não pude ir à escola.","ko-g56-u05.s.1":"Nevou, então a rua está escorregadia.","ko-g56-u05.s.2":"Eu estava com tanto sono que tirei uma soneca.","ko-g56-u05.s.3":"Eu estava atrasado, então peguei um táxi.","ko-g56-u05.s.4":"Fiquei contente de ver meu amigo de novo.","ko-g56-u05.s.5":"Choveu, então eu fiquei em casa.","ko-g56-u05.s.6":"Eu fui à escola e encontrei meu amigo.","ko-g56-u05.s.7":"Eu me machuquei, então passei uma pomada.","ko-g56-u05.g.title":"Porque, então: -아서 / -어서","ko-g56-u05.g.x.0":"Para dar um motivo, pegue a forma com 요, tire o 요 e acrescente 서: 고파요 → 고파서. 배가 고파서 먹었어요 (eu estava com fome, então comi).","ko-g56-u05.g.x.1":"Os verbos em 하다 viram 해서: 피곤해서, 공부해서.","ko-g56-u05.g.x.2":"Só o último verbo mostra o passado: 늦잠을 자서 늦었어요 — nunca 잤어서.","ko-g56-u05.g.x.3":"-아서/어서 também liga passos em ordem: 시장에 가서 과일을 샀어요 (eu fui à feira e comprei frutas).","ko-g56-u05.g.0":"Eu estava com fome, então comi pão.","ko-g56-u05.g.1":"Eu perdi a hora, então me atrasei.","ko-g56-u05.g.2":"Eu estava com febre, então fui ao hospital.","ko-g56-u05.g.3":"Eu estava tão cansado que fui dormir cedo.","ko-g56-u05.g.4":"Prazer em te conhecer.","ko-g56-u05.g.5":"Eu perdi o ônibus, então me atrasei.","ko-g56-u05.g.5.task":"Junte com -어서 (então).","ko-g56-u05.g.6":"A rua estava escorregadia, então eu caí.","ko-g56-u05.g.6.task":"Junte com -어서 (então).","ko-g56-u05.g.7":"Eu fui à feira e comprei frutas.","ko-g56-u05.g.7.task":"Junte os passos com -아서.","ko-g56-u06.title":"Mas: -지만","ko-g56-u06.tip":"No Ano-Novo Lunar, as crianças fazem uma reverência aos mais velhos e dizem 새해 복 많이 받으세요 (muita sorte no ano-novo).","ko-g56-u06.w.0":"Ano-Novo Lunar","ko-g56-u06.w.1":"feriado tradicional","ko-g56-u06.w.2":"Chuseok (festa da colheita)","ko-g56-u06.w.3":"reverência de Ano-Novo","ko-g56-u06.w.4":"dinheiro de Ano-Novo","ko-g56-u06.w.5":"sopa de bolinho de arroz","ko-g56-u06.w.6":"hanbok (roupa tradicional)","ko-g56-u06.w.7":"parentes","ko-g56-u06.w.8":"reunir-se","ko-g56-u06.w.9":"receber, ganhar","ko-g56-u06.w.10":"tradição","ko-g56-u06.w.11":"mas, porém","ko-g56-u06.s.0":"O Chuseok é no outono.","ko-g56-u06.s.1":"O Ano-Novo Lunar é corrido, mas divertido.","ko-g56-u06.s.2":"Lá fora está frio, mas em casa está quentinho.","ko-g56-u06.s.3":"Meu irmãozinho é pequeno, mas forte.","ko-g56-u06.s.4":"Estou cheio. Mas quero comer mais.","ko-g56-u06.s.5":"No Ano-Novo Lunar, os parentes se reúnem.","ko-g56-u06.s.6":"Eu fiz a reverência de Ano-Novo para o meu avô.","ko-g56-u06.s.7":"Eu ganhei muito dinheiro de Ano-Novo.","ko-g56-u06.g.title":"Mas: -지만 · 하지만","ko-g56-u06.g.x.0":'Para dizer "mas" dentro de uma frase, tire o 다 e acrescente 지만: 맛있다 → 맛있지만. 맛있지만 뜨거워요 (é gostoso, mas está quente).',"ko-g56-u06.g.x.1":"O -지만 funciona do mesmo jeito com todos os verbos e palavras que descrevem: 춥지만, 예쁘지만, 했지만.","ko-g56-u06.g.x.2":'Para começar uma frase nova com "mas", use 하지만: 피곤해요. 하지만 행복해요.',"ko-g56-u06.g.0":"A sopa de bolinho de arroz é gostosa, mas está quente.","ko-g56-u06.g.1":"Está frio, mas eu estou bem.","ko-g56-u06.g.2":"O hanbok é bonito, mas um pouco desconfortável.","ko-g56-u06.g.3":"Meu irmãozinho é pequeno, mas esperto.","ko-g56-u06.g.4":"Estou cansado. Mas estou feliz.","ko-g56-u06.g.5":"Estudar é difícil, mas divertido.","ko-g56-u06.g.5.task":"Faça uma frase só com -지만.","ko-g56-u06.g.6":"Ontem choveu, mas hoje está aberto.","ko-g56-u06.g.6.task":"Faça uma frase só com -지만.","ko-g56-u06.g.7":"Meu irmão mais velho é alto, mas eu sou baixinho.","ko-g56-u06.g.7.task":"Faça uma frase só com -지만.","ko-g56-u06.r.ko":"Manhã de Ano-Novo","ko-g56-u06.r.genre":"Cultura","ko-g56-u06.r.p.0":"É manhã de Ano-Novo. A Jiwoo acordou cedo e vestiu o hanbok. O hanbok é bonito, mas um pouco desconfortável. Todos os parentes se reuniram na casa do avô.","ko-g56-u06.r.p.1":'A Jiwoo fez a reverência de Ano-Novo para o avô e a avó. "Feliz Ano-Novo!" O avô sorriu e deu a ela dinheiro de Ano-Novo.',"ko-g56-u06.r.p.2":"De manhã, todos comeram juntos sopa de bolinho de arroz. Na Coreia, dizem que comer essa sopa faz você ficar um ano mais velho. À tarde, a Jiwoo jogou yunnori, um jogo de tabuleiro, com os primos. Ela perdeu, mas se divertiu muito.","ko-g56-u07.title":"Maior, o maior de todos","ko-g56-u07.tip":"Compare as coisas ao seu redor: 아빠가 엄마보다 커요. 고양이가 강아지보다 작아요. Quem é 제일 na sua família?","ko-g56-u07.w.0":"do que","ko-g56-u07.w.1":"mais","ko-g56-u07.w.2":"menos","ko-g56-u07.w.3":"o mais","ko-g56-u07.w.4":"alto, elevado","ko-g56-u07.w.5":"baixo","ko-g56-u07.w.6":"largo, espaçoso","ko-g56-u07.w.7":"estreito","ko-g56-u07.w.8":"cidade","ko-g56-u07.w.9":"interior (campo)","ko-g56-u07.w.10":"primo","ko-g56-u07.w.11":"comparação","ko-g56-u07.s.0":"O papai é mais alto do que a mamãe.","ko-g56-u07.s.1":"A cidade é mais barulhenta do que o interior.","ko-g56-u07.s.2":"Este kimchi é menos apimentado do que aquele kimchi.","ko-g56-u07.s.3":"O Minjun é o mais rápido da nossa turma.","ko-g56-u07.s.4":"Uma montanha é mais alta do que um morro.","ko-g56-u07.s.5":"De todos os animais, eu gosto mais de gatos.","ko-g56-u07.s.6":"Meu quarto é menor do que o do meu irmãozinho.","ko-g56-u07.s.7":"Meu primo é um ano mais velho do que eu.","ko-g56-u07.g.title":"Comparar: 보다 (더) · 제일 / 가장","ko-g56-u07.g.x.0":"Para comparar, coloque 보다 depois da coisa com que você compara: 형이 저보다 커요 (meu irmão é mais alto do que eu).","ko-g56-u07.g.x.1":"Você pode acrescentar 더 (mais) ou 덜 (menos): 서울이 부산보다 더 커요.","ko-g56-u07.g.x.2":'Para "o mais", use 제일 ou 가장: 제일 빨라요 (é o mais rápido). Acrescente 에서 para o grupo: 우리 반에서 제일 빨라요.',"ko-g56-u07.g.0":"Meu irmão mais velho é mais alto do que eu.","ko-g56-u07.g.1":"Seul é maior do que Busan.","ko-g56-u07.g.2":"Hoje está menos frio do que ontem.","ko-g56-u07.g.3":"O Minjun é o mais rápido.","ko-g56-u07.g.4":"O que eu mais gosto é o verão.","ko-g56-u07.g.5":"O interior é mais tranquilo do que a cidade.","ko-g56-u07.g.5.task":"Compare com a cidade: acrescente 도시보다.","ko-g56-u07.g.6":"Esta rua é mais larga do que aquela rua.","ko-g56-u07.g.6.task":"Compare com aquela rua: acrescente 저 길보다.","ko-g56-u07.g.7":"A Jiwoo é a mais alta da nossa turma.","ko-g56-u07.g.7.task":'Diga "a mais alta": acrescente 제일.',"ko-g56-u08.title":"Uma criança gentil, um livro divertido","ko-g56-u08.tip":"Descreva suas coisas favoritas: 제가 좋아하는 색, 제가 좋아하는 동물, 제가 좋아하는 음식은 …","ko-g56-u08.w.0":"novo","ko-g56-u08.w.1":"velho, usado","ko-g56-u08.w.2":"antigamente, os velhos tempos","ko-g56-u08.w.3":"gentil, bondoso","ko-g56-u08.w.4":"fofo","ko-g56-u08.w.5":"famoso","ko-g56-u08.w.6":"silencioso","ko-g56-u08.w.7":"barulhento","ko-g56-u08.w.8":"simpático","ko-g56-u08.w.9":"chato","ko-g56-u08.w.10":"igual","ko-g56-u08.w.11":"diferente","ko-g56-u08.s.0":"A vovó tem um gato fofo.","ko-g56-u08.s.1":"A criança gentil ajuda o irmãozinho.","ko-g56-u08.s.2":"Eu leio na biblioteca silenciosa.","ko-g56-u08.s.3":"Este é um restaurante famoso.","ko-g56-u08.s.4":"Eu gosto de professores gentis.","ko-g56-u08.s.5":"O desenho que meu irmão mais velho está vendo é divertido.","ko-g56-u08.s.6":"Minha cor favorita é verde.","ko-g56-u08.s.7":"Eu calço sapatos novos.","ko-g56-u08.g.title":"Descrever um substantivo: -(으)ㄴ / -는","ko-g56-u08.g.x.0":"Para colocar uma palavra que descreve antes de um substantivo, tire o 다 e acrescente ㄴ: 착하다 → 착한 아이 (uma criança gentil), 크다 → 큰 집.","ko-g56-u08.g.x.1":"Depois de uma letra embaixo, acrescente 은: 작다 → 작은 고양이. Palavras que terminam em 있다/없다 ganham 는: 재미있는 책.","ko-g56-u08.g.x.2":"Para ações que estão acontecendo, acrescente 는: 읽다 → 읽는 책 (o livro que estou lendo), 좋아하다 → 좋아하는 음식 (comida favorita).","ko-g56-u08.g.0":"É uma criança gentil.","ko-g56-u08.g.1":"Tem um gato pequeno.","ko-g56-u08.g.2":"Eu leio um livro divertido.","ko-g56-u08.g.3":"Minha comida favorita é tteokbokki.","ko-g56-u08.g.4":"Eu estudo na biblioteca silenciosa.","ko-g56-u08.g.5":"Eu tenho um cachorrinho fofo.","ko-g56-u08.g.5.task":'Coloque "fofo" antes de 강아지 numa frase só.',"ko-g56-u08.g.6":"Esta é uma música famosa.","ko-g56-u08.g.6.task":'Diga "uma música famosa": coloque 유명한 antes de 노래.',"ko-g56-u08.g.7":"O livro que estou lendo agora é divertido.","ko-g56-u08.g.7.task":"Faça uma frase só: 읽는 책.","ko-g56-u09.title":"Respeito aos mais velhos","ko-g56-u09.tip":"Os avós coreanos costumam chamar os netos, com carinho, de 우리 강아지 (meu cachorrinho). É um apelido muito fofo!","ko-g56-u09.w.0":"casa (de um mais velho)","ko-g56-u09.w.1":"refeição (de um mais velho)","ko-g56-u09.w.2":"coma, por favor (a um mais velho)","ko-g56-u09.w.3":"dormir (um mais velho)","ko-g56-u09.w.4":"estar (um mais velho)","ko-g56-u09.w.5":"para (um mais velho)","ko-g56-u09.w.6":"dar (a um mais velho)","ko-g56-u09.w.7":"idade (de um mais velho)","ko-g56-u09.w.8":"palavras (de um mais velho)","ko-g56-u09.w.9":"linguagem respeitosa","ko-g56-u09.w.10":"adulto","ko-g56-u09.w.11":"neto","ko-g56-u09.s.0":"Vovô, aceite isto, por favor.","ko-g56-u09.s.1":"A professora está na sala de aula.","ko-g56-u09.s.2":"O vovô está dormindo agora.","ko-g56-u09.s.3":"Eu dei flores para a vovó.","ko-g56-u09.s.4":"O vovô está lendo o jornal.","ko-g56-u09.s.5":"Eu escuto com atenção o meu professor.","ko-g56-u09.s.6":"Com os adultos, usamos linguagem respeitosa.","ko-g56-u09.s.7":"Quantos anos tem o seu avô?","ko-g56-u09.g.title":"Mostrar respeito: -(으)세요 · 께 · palavras especiais","ko-g56-u09.g.x.0":"Quando falar de uma pessoa mais velha, acrescente 시 ao verbo: 가요 → 가세요, 웃어요 → 웃으세요 (a vovó está sorrindo).","ko-g56-u09.g.x.1":"Algumas palavras mudam completamente: 먹어요 → 드세요, 자요 → 주무세요, 있어요 → 계세요, 집 → 댁, 나이 → 연세.","ko-g56-u09.g.x.2":'Use 께 para dizer "para" um mais velho (할머니께 드려요) e 께서 no lugar de 이/가 (할머니께서 웃으세요).',"ko-g56-u09.g.0":"Vovó, coma, por favor.","ko-g56-u09.g.1":"O vovô está no quarto dele.","ko-g56-u09.g.2":"Boa noite, vovó.","ko-g56-u09.g.3":"Eu dei uma carta para a minha professora.","ko-g56-u09.g.4":"A vovó está sorrindo.","ko-g56-u09.g.5":"Eu vou à casa do vovô.","ko-g56-u09.g.5.task":"Use a palavra respeitosa para a casa de um mais velho: 댁.","ko-g56-u09.g.6":"Quantos anos tem a sua avó?","ko-g56-u09.g.6.task":"Use a palavra respeitosa para a idade de um mais velho: 연세.","ko-g56-u09.g.7":"Eu dou um presente para o papai.","ko-g56-u09.g.7.task":"Use o verbo respeitoso para dar algo a um mais velho: 드려요.","ko-g56-u09.r.ko":"Na casa da vovó","ko-g56-u09.r.genre":"História","ko-g56-u09.r.p.0":'No sábado, o Hajun foi à casa da avó, no interior. A vovó estava esperando na frente da porta. "Olá, vovó!", cumprimentou o Hajun bem alto.',"ko-g56-u09.r.p.1":'À noite, a vovó fez um ensopado de pasta de soja delicioso. O Hajun entregou uma colher para a vovó. "Vovó, coma, por favor." A vovó sorriu e disse: "Meu neto é o melhor!"',"ko-g56-u09.r.p.2":'Mais tarde, a vovó contou uma história antiga. O Hajun pegou no sono enquanto escutava. A vovó cobriu ele com um cobertor. "Durma bem, meu cachorrinho."',"ko-g56-u09.r.q.2.o.0":"neto","ko-g56-u09.r.q.2.o.1":"avó","ko-g56-u09.r.q.2.o.2":"vizinho","ko-g56-u10.title":"Experimente","ko-g56-u10.tip":"Pergunte à sua família sobre as experiências deles: 한국 음식을 먹어 봤어요? 태권도를 해 봤어요?","ko-g56-u10.w.0":"experiência","ko-g56-u10.w.1":"a primeira vez","ko-g56-u10.w.2":"uma vez","ko-g56-u10.w.3":"sabor","ko-g56-u10.w.4":"cheiro","ko-g56-u10.w.5":"incrível, fascinante","ko-g56-u10.w.6":"bibimbap","ko-g56-u10.w.7":"taekwondo","ko-g56-u10.w.8":"casa tradicional coreana","ko-g56-u10.w.9":"calçar (sapatos, meias)","ko-g56-u10.w.10":"que tal?","ko-g56-u10.w.11":"brinquedo (de parque)","ko-g56-u10.s.0":"Experimente este kimchi também.","ko-g56-u10.s.1":"Você já experimentou tteokbokki?","ko-g56-u10.s.2":"Sim, já experimentei uma vez.","ko-g56-u10.s.3":"Experimente este chapéu.","ko-g56-u10.s.4":"Eu quero experimentar aprender taekwondo.","ko-g56-u10.s.5":"Eu dormi num hanok pela primeira vez.","ko-g56-u10.s.6":"Que gosto tem?","ko-g56-u10.s.7":"Foi uma experiência incrível de verdade.","ko-g56-u10.g.title":"Experimente: -아/어 보세요 · -아/어 봤어요","ko-g56-u10.g.x.0":'Acrescente 보세요 à forma em -아/어 para dizer "experimente fazer": 먹어 보세요 (experimente comer), 입어 보세요 (experimente vestir).',"ko-g56-u10.g.x.1":"봤어요 quer dizer que você já experimentou antes: 먹어 봤어요 (eu já comi).","ko-g56-u10.g.x.2":"Pergunte sobre experiências com 봤어요?: 한국에 가 봤어요? — Você já foi à Coreia?","ko-g56-u10.g.0":"Experimente este bolinho de arroz.","ko-g56-u10.g.1":"Experimente estas roupas.","ko-g56-u10.g.2":"Você já experimentou bibimbap?","ko-g56-u10.g.3":"Eu já fui à Coreia.","ko-g56-u10.g.4":"Experimente aprender taekwondo.","ko-g56-u10.g.5":"Eu já dormi num hanok.","ko-g56-u10.g.5.task":"Diga que você já teve a experiência: use -아 봤어요.","ko-g56-u10.g.6":"Experimente calçar estes sapatos.","ko-g56-u10.g.6.task":"Convide a experimentar: use -어 보세요.","ko-g56-u10.g.7":"Você já foi naquele brinquedo?","ko-g56-u10.g.7.task":"Pergunte sobre a experiência: use -아 봤어요?","ko-g56-u11.title":"Vamos…?","ko-g56-u11.tip":"Na Coreia, dá para pedir comida por entrega em quase qualquer lugar — até num parque à beira do rio!","ko-g56-u11.w.0":"piquenique, passeio","ko-g56-u11.w.1":"marmita","ko-g56-u11.w.2":"toalha de piquenique","ko-g56-u11.w.3":"frango frito","ko-g56-u11.w.4":"entrega","ko-g56-u11.w.5":"o rio Han","ko-g56-u11.w.6":"soltar (pipa)","ko-g56-u11.w.7":"pegar emprestado, alugar","ko-g56-u11.w.8":"pedir (comida)","ko-g56-u11.w.9":"juntos","ko-g56-u11.w.10":"paisagem, vista","ko-g56-u11.w.11":"pôr do sol avermelhado","ko-g56-u11.s.0":"Vamos ao parque amanhã?","ko-g56-u11.s.1":"Que horas a gente se encontra?","ko-g56-u11.s.2":"Vamos pedir pizza?","ko-g56-u11.s.3":"Vamos soltar pipa juntos?","ko-g56-u11.s.4":"Vamos estender a toalha aqui?","ko-g56-u11.s.5":"A gente solta pipa no rio Han.","ko-g56-u11.s.6":"O pôr do sol está lindo.","ko-g56-u11.s.7":"O que a gente vai comer hoje?","ko-g56-u11.g.title":"Vamos…?: -(으)ㄹ까요?","ko-g56-u11.g.x.0":"Para sugerir fazer algo juntos, tire o 다 e acrescente ㄹ까요?: 가다 → 갈까요? (vamos?)","ko-g56-u11.g.x.1":"Depois de uma letra embaixo, acrescente 을까요?: 먹다 → 먹을까요?, 앉다 → 앉을까요?","ko-g56-u11.g.x.2":"Responda com 네, 좋아요! ou sugira outra coisa com a forma em 요: 공원에 가요! (vamos ao parque!)","ko-g56-u11.g.0":"Vamos fazer um piquenique neste fim de semana?","ko-g56-u11.g.1":"O que a gente come?","ko-g56-u11.g.2":"Onde a gente se encontra?","ko-g56-u11.g.3":"Vamos andar de bicicleta juntos?","ko-g56-u11.g.4":"Vamos sentar aqui?","ko-g56-u11.g.5":"Vamos pedir frango frito?","ko-g56-u11.g.5.task":"Transforme em sugestão: use -을까요?","ko-g56-u11.g.6":"Vamos soltar pipa no rio Han?","ko-g56-u11.g.6.task":"Transforme em sugestão: use -ㄹ까요?","ko-g56-u11.g.7":"Vamos juntos à biblioteca hoje?","ko-g56-u11.g.7.task":"Transforme em sugestão: use -ㄹ까요?","ko-g56-u11.r.ko":"Um piquenique no rio Han","ko-g56-u11.r.genre":"Diário","ko-g56-u11.r.p.0":"Domingo, 3 de outubro. O tempo estava aberto. Minha família foi fazer um piquenique no rio Han. A mamãe preparou marmitas de gimbap para a gente.","ko-g56-u11.r.p.1":'O papai perguntou: "Vamos alugar bicicletas e dar uma volta?" A gente pedalou ao longo do rio. O vento estava fresco, e eu me senti muito bem.',"ko-g56-u11.r.p.2":"Na hora do almoço, estendemos a toalha e comemos as marmitas. Meu irmãozinho disse que também queria frango. Então pedimos frango por entrega. Foi incrível a comida chegar até no rio Han.","ko-g56-u11.r.p.3":"À tardinha, soltamos pipa e vimos o pôr do sol. O céu ficou vermelho e estava lindo. Quero voltar no próximo fim de semana.","ko-g56-u11.r.q.3.o.0":"o céu vermelho do pôr do sol","ko-g56-u11.r.q.3.o.1":"uma pipa","ko-g56-u11.r.q.3.o.2":"uma toalha de piquenique","ko-g56-u12.title":"Por favor, não…","ko-g56-u12.tip":"Na Coreia, você vai ver -지 마세요 nas placas: 만지지 마세요 (não toque), 들어가지 마세요 (não entre).","ko-g56-u12.w.0":"fazer barulho, tagarelar","ko-g56-u12.w.1":"tocar","ko-g56-u12.w.2":"jogar fora","ko-g56-u12.w.3":"lixo","ko-g56-u12.w.4":"perigoso","ko-g56-u12.w.5":"preocupar-se","ko-g56-u12.w.6":"travessura","ko-g56-u12.w.7":"galeria de arte","ko-g56-u12.w.8":"obra de arte","ko-g56-u12.w.9":"filmar, tirar fotos","ko-g56-u12.w.10":"comida (e bebida)","ko-g56-u12.w.11":"ter pressa","ko-g56-u12.s.0":"Não faça barulho na biblioteca.","ko-g56-u12.s.1":"Não toque no quadro.","ko-g56-u12.s.2":"Não jogue lixo na rua.","ko-g56-u12.s.3":"Não se preocupe tanto.","ko-g56-u12.s.4":"Não corra na rua. É perigoso.","ko-g56-u12.s.5":"Não tenha pressa na escada.","ko-g56-u12.s.6":"Não tire fotos na galeria de arte.","ko-g56-u12.s.7":"Não faça travessuras com o seu amigo.","ko-g56-u12.g.title":"Não faça: -지 마세요","ko-g56-u12.g.x.0":"Para pedir com educação que alguém não faça algo, tire o 다 e acrescente 지 마세요: 만지다 → 만지지 마세요 (não toque).","ko-g56-u12.g.x.1":"Funciona do mesmo jeito com todos os verbos: 먹지 마세요, 뛰지 마세요, 걱정하지 마세요.","ko-g56-u12.g.x.2":"Para um amigo próximo, você pode dizer -지 마: 울지 마! (Não chora!)","ko-g56-u12.g.0":"Não toque na obra de arte.","ko-g56-u12.g.1":"Não se preocupe.","ko-g56-u12.g.2":"Não faça barulho na sala de aula.","ko-g56-u12.g.3":"Não corra na rua.","ko-g56-u12.g.4":"Não coma aqui.","ko-g56-u12.g.5":"Não jogue lixo no chão.","ko-g56-u12.g.5.task":'Transforme em "não": use -지 마세요.',"ko-g56-u12.g.6":"Não tire fotos na galeria de arte.","ko-g56-u12.g.6.task":'Transforme em "não": use -지 마세요.',"ko-g56-u12.g.7":"Não tenha pressa.","ko-g56-u12.g.7.task":'Transforme em "não": use -지 마세요.',"ko-g56-u13.title":"Antes e depois","ko-g56-u13.tip":"Prepare gimbap (ou qualquer comida simples) com a sua família e diga cada passo em coreano: 먼저 …, 그다음에 …, 마지막으로 …","ko-g56-u13.w.0":"ingredientes","ko-g56-u13.w.1":"alga seca","ko-g56-u13.w.2":"espalhar","ko-g56-u13.w.3":"enrolar","ko-g56-u13.w.4":"fatiar","ko-g56-u13.w.5":"faca","ko-g56-u13.w.6":"misturar","ko-g56-u13.w.7":"óleo de gergelim","ko-g56-u13.w.8":"presunto","ko-g56-u13.w.9":"rabanete amarelo em conserva","ko-g56-u13.w.10":"último","ko-g56-u13.w.11":"tomar cuidado","ko-g56-u13.s.0":"Eu leio um livro antes de dormir.","ko-g56-u13.s.1":"Eu como um lanchinho depois de arrumar.","ko-g56-u13.s.2":"Eu tomo café da manhã antes de ir para a escola.","ko-g56-u13.s.3":"Eu tomo banho depois de nadar.","ko-g56-u13.s.4":"Eu lavo os ingredientes antes de cozinhar.","ko-g56-u13.s.5":"Espalhe o arroz sobre a alga.","ko-g56-u13.s.6":"Tome cuidado quando usar a faca.","ko-g56-u13.s.7":"Por último, fatie o gimbap.","ko-g56-u13.g.title":"Antes e depois: -기 전에 · -(으)ㄴ 후에","ko-g56-u13.g.x.0":'"Antes de fazer": tire o 다 e acrescente 기 전에: 먹다 → 먹기 전에 (antes de comer).',"ko-g56-u13.g.x.1":'"Depois de fazer": tire o 다 e acrescente ㄴ 후에: 하다 → 한 후에. Depois de uma letra embaixo, acrescente 은 후에: 먹다 → 먹은 후에.',"ko-g56-u13.g.x.2":"Com substantivos, é só acrescentar 전에 ou 후에: 수업 전에, 방학 후에.","ko-g56-u13.g.0":"Eu lavo as mãos antes de comer.","ko-g56-u13.g.1":"Eu brinco depois de fazer a lição de casa.","ko-g56-u13.g.2":"Eu escovo os dentes antes de dormir.","ko-g56-u13.g.3":"Eu dou uma volta depois de comer.","ko-g56-u13.g.4":"Depois que a aula acaba, eu vou para o taekwondo.","ko-g56-u13.g.5":"Antes de fazer gimbap, preparamos os ingredientes.","ko-g56-u13.g.5.task":"Use -기 전에 para fazer uma frase só.","ko-g56-u13.g.6":"A gente come depois de ver um filme.","ko-g56-u13.g.6.task":"Use -ㄴ 후에 para fazer uma frase só.","ko-g56-u13.g.7":"Eu visto o pijama depois de tomar banho.","ko-g56-u13.g.7.task":"Use -ㄴ 후에 para fazer uma frase só.","ko-g56-u13.r.ko":"Vamos fazer gimbap","ko-g56-u13.r.genre":"Receita","ko-g56-u13.r.p.0":"O gimbap é uma comida que os coreanos costumam levar quando fazem piquenique. Hoje eu vou fazer gimbap com a mamãe. Antes de começar, lavo bem as mãos.","ko-g56-u13.r.p.1":"Primeiro, separe os ingredientes. Você precisa de alga, arroz, ovo, presunto, rabanete em conserva e espinafre. Coloque sal e óleo de gergelim no arroz e misture. A mamãe corta o presunto e o ovo em tiras compridas com a faca. Facas são perigosas, então um adulto deve usá-las.","ko-g56-u13.r.p.2":"Espalhe uma camada fina de arroz sobre a alga. Depois de colocar o recheio por cima, enrole bem firme. Por último, a mamãe fatiou o gimbap para mim. O gimbap que eu fiz ficou uma delícia!","ko-g56-u14.title":"Conversando com amigos","ko-g56-u14.tip":"Na Coreia, você só pode usar 반말 quando é próximo da pessoa e tem mais ou menos a mesma idade. Na dúvida, mantenha o 요 — é sempre seguro.","ko-g56-u14.w.0":"linguagem informal","ko-g56-u14.w.1":"ser próximos (amigos)","ko-g56-u14.w.2":'é ("sim" informal)',"ko-g56-u14.w.3":'não, nada ("não" informal)',"ko-g56-u14.w.4":"valeu (informal)","ko-g56-u14.w.5":"foi mal (informal)","ko-g56-u14.w.6":"tá tudo bem (informal)","ko-g56-u14.w.7":"tá fazendo o quê? (informal)","ko-g56-u14.w.8":"vamos brincar","ko-g56-u14.w.9":"sério? (informal)","ko-g56-u14.w.10":"relação","ko-g56-u14.w.11":"a mesma idade","ko-g56-u14.s.0":"A gente tem a mesma idade?","ko-g56-u14.s.1":"É, eu também tenho dez.","ko-g56-u14.s.2":"O que você vai fazer hoje?","ko-g56-u14.s.3":"Vamos lá pra minha casa!","ko-g56-u14.s.4":"Foi mal por aquela hora.","ko-g56-u14.s.5":"Tá tudo bem, não se preocupa.","ko-g56-u14.s.6":"Essa música é muito boa!","ko-g56-u14.s.7":"Com o nosso professor, usamos linguagem respeitosa.","ko-g56-u14.g.title":"Linguagem informal com amigos: tire o 요","ko-g56-u14.g.x.0":"Com amigos próximos e crianças mais novas, os coreanos usam 반말 (linguagem informal). Na maioria das vezes, é só tirar o 요: 가요 → 가, 먹어요 → 먹어.","ko-g56-u14.g.x.1":"이에요/예요 viram 이야/야: 학생이에요 → 학생이야, 친구예요 → 친구야.","ko-g56-u14.g.x.2":'"Vamos…" para um amigo é -자: 가자! 먹자! 놀자! E 네 → 응, 아니요 → 아니.',"ko-g56-u14.g.x.3":"Use sempre 요 com adultos, professores e pessoas que você acabou de conhecer!","ko-g56-u14.g.0":"O que você tá fazendo agora?","ko-g56-u14.g.1":"Eu também tenho dez anos.","ko-g56-u14.g.2":"Esse é o meu amigo.","ko-g56-u14.g.3":"Vamos comer juntos!","ko-g56-u14.g.4":"Foi mal pelo atraso.","ko-g56-u14.g.5":"Vamos brincar juntos!","ko-g56-u14.g.5.task":"Diga para um amigo próximo: use -자.","ko-g56-u14.g.6":"Esse jogo é muito divertido!","ko-g56-u14.g.6.task":"Diga para um amigo próximo: tire o 요 e use 진짜.","ko-g56-u14.g.7":"Eu sou estudante.","ko-g56-u14.g.7.task":"Diga em 반말: 저는 → 나는, 이에요 → 이야.","ko-g56-u15.title":"Quando…: -(으)ㄹ 때","ko-g56-u15.tip":"Fale de sentimentos com -ㄹ 때: 기쁠 때 노래해요. 슬플 때 엄마를 안아요. O que você faz quando está entediado?","ko-g56-u15.w.0":"com sono","ko-g56-u15.w.1":"com sede","ko-g56-u15.w.2":"curioso","ko-g56-u15.w.3":"chateado","ko-g56-u15.w.4":"sentindo-se sozinho","ko-g56-u15.w.5":"difícil, duro","ko-g56-u15.w.6":"consolar","ko-g56-u15.w.7":"a sós","ko-g56-u15.w.8":"pensamento","ko-g56-u15.w.9":"lembrança","ko-g56-u15.w.10":"quando eu era pequeno","ko-g56-u15.w.11":"sala de karaokê","ko-g56-u15.s.0":"Quando estou entediado, eu desenho.","ko-g56-u15.s.1":"Quando estou com fome, como uma maçã.","ko-g56-u15.s.2":"Quando estou curioso, pergunto para a professora.","ko-g56-u15.s.3":"Quando meu amigo está chateado, eu consolo ele.","ko-g56-u15.s.4":"Quando estou sozinho, leio livros.","ko-g56-u15.s.5":"Quando eu era pequeno, morava no interior.","ko-g56-u15.s.6":"Quando as coisas ficam difíceis, penso no meu amigo.","ko-g56-u15.s.7":"Eu fico animado quando vou ao karaokê.","ko-g56-u15.g.title":"Quando: -(으)ㄹ 때","ko-g56-u15.g.x.0":'Para dizer "quando (algo acontece)", tire o 다 e acrescente ㄹ 때: 졸리다 → 졸릴 때 (quando estou com sono).',"ko-g56-u15.g.x.1":"Depois de uma letra embaixo, acrescente 을 때: 먹다 → 먹을 때, 있다 → 있을 때.","ko-g56-u15.g.x.2":"Para o passado, use 았/었을 때: 어렸을 때 (quando eu era pequeno). Com substantivos, é só acrescentar 때: 방학 때, 점심 때.","ko-g56-u15.g.0":"Quando estou com sono, lavo o rosto.","ko-g56-u15.g.1":"Não fale enquanto come.","ko-g56-u15.g.2":"Quando estou sozinho, escuto música.","ko-g56-u15.g.3":"Quando estiver curioso, pergunte.","ko-g56-u15.g.4":"Nas férias, eu vou à casa da vovó.","ko-g56-u15.g.5":"Quando estou com sede, bebo água.","ko-g56-u15.g.5.task":"Use -ㄹ 때 para fazer uma frase só.","ko-g56-u15.g.6":"Quando estou chateado, a mamãe me consola.","ko-g56-u15.g.6.task":"Use -ㄹ 때 para fazer uma frase só.","ko-g56-u15.g.7":"Quando eu era pequeno, morava no interior.","ko-g56-u15.g.7.task":"Use -았/었을 때 para fazer uma frase só.","ko-g56-u16.title":"Contando uma história","ko-g56-u16.tip":"Heungbu e Nolbu é um dos contos populares coreanos mais conhecidos. Reconte a história para a sua família com 먼저, 그다음에, 그런데 e 마지막으로!","ko-g56-u16.w.0":"primeiro","ko-g56-u16.w.1":"em seguida, depois","ko-g56-u16.w.2":"mas, e aí","ko-g56-u16.w.3":"de repente","ko-g56-u16.w.4":"por fim, no final","ko-g56-u16.w.5":"ganância","ko-g56-u16.w.6":"pobre","ko-g56-u16.w.7":"pessoa rica","ko-g56-u16.w.8":"andorinha","ko-g56-u16.w.9":"semente","ko-g56-u16.w.10":"cabaça","ko-g56-u16.w.11":"tesouro","ko-g56-u16.s.0":"Primeiro, eu faço a lição de casa.","ko-g56-u16.s.1":"Depois, eu brinco com o cachorrinho.","ko-g56-u16.s.2":"Por fim, eu escrevo no meu diário.","ko-g56-u16.s.3":"A gente foi fazer piquenique. Mas esquecemos o lanche.","ko-g56-u16.s.4":"De repente, veio um cachorrinho correndo.","ko-g56-u16.s.5":"Minha barriga está doendo. Então eu vou ao hospital.","ko-g56-u16.s.6":"O Nolbu era muito ganancioso.","ko-g56-u16.s.7":"Saiu um tesouro de dentro da cabaça.","ko-g56-u16.g.title":"Contar as coisas em ordem: 먼저, 그다음에, 그래서, 그런데","ko-g56-u16.g.x.0":"Use estas palavras no começo da frase para contar as coisas em ordem: 먼저 (primeiro) → 그다음에 (depois) → 마지막으로 (por fim).","ko-g56-u16.g.x.1":'그래서 quer dizer "então" (um resultado): 비가 와요. 그래서 집에 있어요.',"ko-g56-u16.g.x.2":'그런데 quer dizer "mas" ou "e aí" (algo inesperado): 공원에 갔어요. 그런데 문이 닫혀 있었어요.',"ko-g56-u16.g.x.3":'갑자기 quer dizer "de repente": 갑자기 불이 꺼졌어요.',"ko-g56-u16.g.0":"Primeiro, lave as mãos.","ko-g56-u16.g.1":"Depois, coma.","ko-g56-u16.g.2":"Está chovendo. Então eu uso guarda-chuva.","ko-g56-u16.g.3":"Eu fui ao parque. Mas aí choveu.","ko-g56-u16.g.4":"Por fim, escove os dentes.","ko-g56-u16.g.5":"Eu estava com fome. Então comi pão.","ko-g56-u16.g.5.task":"Divida em duas frases com 그래서.","ko-g56-u16.g.6":"Eu estava andando. De repente, choveu.","ko-g56-u16.g.6.task":'Acrescente "de repente": use 갑자기.',"ko-g56-u16.g.7":"Primeiro eu faço a lição de casa. Depois eu brinco.","ko-g56-u16.g.7.task":"Conte em dois passos: 먼저 … 그다음에 …","ko-g56-u16.r.ko":"Heungbu e Nolbu","ko-g56-u16.r.genre":"Conto popular","ko-g56-u16.r.p.0":"Era uma vez dois irmãos, Heungbu e Nolbu. O irmão mais velho, Nolbu, era rico, mas muito ganancioso. O irmão mais novo, Heungbu, era pobre, mas tinha bom coração.","ko-g56-u16.r.p.1":"Num dia de primavera, Heungbu viu uma andorinha com a perna machucada. Ele cuidou da perna da andorinha com muito carinho. Quando chegou o outono, a andorinha voou para o sul quentinho.","ko-g56-u16.r.p.2":"Na primavera seguinte, a andorinha voltou trazendo uma semente de cabaça. Quando Heungbu a plantou, cresceram cabaças enormes. Quando ele abriu uma cabaça, saíram ouro e tesouros!","ko-g56-u16.r.p.3":"Quando Nolbu ouviu a história, machucou a perna de uma andorinha de propósito. Mas das cabaças de Nolbu saíram duendes que o castigaram. No final, Nolbu se arrependeu do que tinha feito e virou uma boa pessoa.","ko-g56-u16.r.q.3.o.0":"a ganância","ko-g56-u16.r.q.3.o.1":"a bondade","ko-g56-u16.r.q.3.o.2":"o tesouro"},r={"tier.first.label":"Primeiras palavras","tier.first.age":"Mesmo sem saber ler","tier.first.desc":"Ouça uma palavra e toque na figura · não precisa ler","tier.kinder.label":"Hangul","tier.kinder.age":"Comece aqui se for novo","tier.kinder.desc":"As letras coreanas e como se juntam · cumprimentos, números, cores","tier.g12.label":"Primeiras frases","tier.g12.age":"Se já lê hangul","tier.g12.desc":"Comida, corpo, escola, tempo · frases curtas","tier.g34.label":"Gramática básica","tier.g34.age":"Se já sabe frases curtas","tier.g34.desc":"Partículas, terminações verbais, passado e futuro · diálogos","tier.g56.label":"Leitura","tier.g56.age":"Se já forma frases","tier.g56.desc":"Poder, dever, fala educada · leituras curtas"},g={...r,...o,...a,...e,...u,...s};export{g as default};
